"use client";

import { useState, useEffect } from "react";
import { createClient } from "@/utils/supabase/client";
import { Users, Briefcase, Zap, TrendingUp, Shield, Crown, Settings } from "lucide-react";
import { settingsHub } from "@/lib/supabase-helpers";

export default function AdminDashboard() {
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    totalMakers: 0,
    totalJobs: 0,
    activeFeatured: 0,
    revenue: "R 0.00"
  });
  const [loadSheddingMode, setLoadSheddingMode] = useState(false);

  useEffect(() => {
    async function fetchStatsAndSettings() {
      const supabase = createClient();

      const { count: makersCount } = await supabase.from('makers').select('*', { count: 'exact', head: true });
      const { count: jobsCount } = await supabase.from('jobs').select('*', { count: 'exact', head: true });
      const { count: featuredCount } = await (supabase.from('makers') as any)
        .select('*', { count: 'exact', head: true })
        .gt('featured_until', new Date().toISOString());

      // Fetch Load Shedding Scale using settingsHub
      const settingValue = await settingsHub.get('load_shedding_mode');

      if (settingValue !== null) {
        setLoadSheddingMode(settingValue === "true" || settingValue === true);
      }

      setStats({
        totalMakers: makersCount || 0,
        totalJobs: jobsCount || 0,
        activeFeatured: featuredCount || 0,
        revenue: `R ${(featuredCount || 0) * 50 + (jobsCount || 0) * 200}.00`
      });
      setLoading(false);
    }
    fetchStatsAndSettings();
  }, []);

  const toggleLoadShedding = async () => {
    const newValue = !loadSheddingMode;
    setLoadSheddingMode(newValue);

    try {
      await settingsHub.set('load_shedding_mode', String(newValue));
    } catch (err) {
      console.error("Failed to toggle load shedding:", err);
      setLoadSheddingMode(!newValue); // Rollback
    }
  };

  if (loading) return <div className="h-screen bg-[#0D110F] flex items-center justify-center text-[#13EC6A]"><Zap className="animate-pulse" size={48} /></div>;

  return (
    <div className="min-h-screen bg-[#0D110F] text-white p-8 lg:p-16 font-body">
      <div className="max-w-7xl mx-auto space-y-16">

        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
           <div className="space-y-4">
              <h1 className="text-6xl font-black italic tracking-tighter font-display uppercase">Command Center.</h1>
              <p className="text-[10px] font-black uppercase tracking-[0.4em] text-gray-500">Platform Management • ShapaCV v1.0</p>
           </div>

           <div className="flex gap-4">
              <div className={`flex items-center gap-4 px-8 py-4 rounded-2xl glass border ${loadSheddingMode ? 'border-amber-500/30' : 'border-white/5'}`}>
                 <div className={`w-3 h-3 rounded-full ${loadSheddingMode ? 'bg-amber-500 animate-pulse shadow-[0_0_10px_amber]' : 'bg-[#13EC6A]'}`} />
                 <span className="text-[10px] font-black uppercase tracking-widest">{loadSheddingMode ? 'Load Shedding Active' : 'Grid Stable'}</span>
                 <button 
                   onClick={toggleLoadShedding}
                   className="ml-4 px-4 py-1.5 bg-white/5 hover:bg-white/10 rounded-lg text-[8px] font-black uppercase transition-all"
                 >
                    Toggle
                 </button>
              </div>
           </div>
        </div>

        {/* Stats Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
           <StatCard icon={<Users />} label="Total Makers" value={stats.totalMakers} color="#13EC6A" />
           <StatCard icon={<Briefcase />} label="Active Gigs" value={stats.totalJobs} color="#3B82F6" />
           <StatCard icon={<Crown />} label="Featured Hustlers" value={stats.activeFeatured} color="#A855F7" />
           <StatCard icon={<TrendingUp />} label="Est. Revenue" value={stats.revenue} color="#F59E0B" />
        </div>

        {/* Management Sections */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
           {/* Recent Activity */}
           <div className="glass-dark rounded-[3.5rem] border border-white/5 p-12">
              <div className="flex justify-between items-center mb-10">
                 <h3 className="text-2xl font-black italic uppercase font-display tracking-tight">System Integrity</h3>
                 <Shield className="text-[#13EC6A]/50" />
              </div>
              <div className="space-y-6">
                 <IntegrityCheck label="Database Sync" status="Operational" />
                 <IntegrityCheck label="Payment Gateway" status="Operational" />
                 <IntegrityCheck label="Video Storage" status="92% Full" warning />
                 <IntegrityCheck label="Messenger Relay" status="Latency High" warning />
              </div>
           </div>

           {/* Quick Actions */}
           <div className="glass-dark rounded-[3.5rem] border border-white/5 p-12 space-y-8">
              <h3 className="text-2xl font-black italic uppercase font-display tracking-tight">Rapid Response</h3>
              <div className="grid grid-cols-2 gap-6">
                 <ActionButton icon={<Zap />} label="Boost Grid" />
                 <ActionButton icon={<Settings />} label="CMS Config" />
                 <ActionButton icon={<Users />} label="Moderate Review" />
                 <ActionButton icon={<Crown />} label="Manual Feature" />
              </div>
           </div>
        </div>
      </div>
    </div>
  );
}

function StatCard({ icon, label, value, color }: { icon: React.ReactNode, label: string, value: string | number, color: string }) {
  return (
    <div className="glass-dark p-10 rounded-[3rem] border border-white/5 hover:border-white/10 transition-all flex flex-col justify-between group">
       <div className="w-14 h-14 rounded-2xl flex items-center justify-center mb-10 border border-white/5 group-hover:scale-110 transition-transform" style={{ color }}>
          {icon}
       </div>
       <div>
          <p className="text-[10px] font-black uppercase tracking-[0.2em] text-gray-600 mb-2 italic">{label}</p>
          <h4 className="text-4xl font-black italic tracking-tighter font-display leading-none">{value}</h4>
       </div>
    </div>
  );
}

function IntegrityCheck({ label, status, warning }: { label: string, status: string, warning?: boolean }) {
  return (
    <div className="flex justify-between items-center p-6 glass rounded-2xl border border-white/5">
       <span className="text-[10px] font-black uppercase tracking-widest text-gray-500 italic">{label}</span>
       <span className={`text-[10px] font-black uppercase tracking-widest ${warning ? 'text-amber-500' : 'text-[#13EC6A]'}`}>{status}</span>
    </div>
  );
}

function ActionButton({ icon, label }: { icon: React.ReactNode, label: string }) {
  return (
    <button className="flex flex-col items-center justify-center p-8 glass rounded-3xl border border-white/5 hover:bg-white/5 hover:border-[#13EC6A]/30 transition-all gap-4 group">
       <div className="text-gray-500 group-hover:text-[#13EC6A] transition-colors">{icon}</div>
       <span className="text-[8px] font-black uppercase tracking-widest text-gray-600 group-hover:text-white transition-colors">{label}</span>
    </button>
  );
}

"use client";

import { useState, useEffect, use } from "react";
import { createClient } from "@/utils/supabase/client";
import { Briefcase, Lock, CheckCircle2, ShieldAlert, Star, DollarSign, Clock, FileText, Send, User } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { submitReview } from "@/lib/actions/reviews";

type Props = {
  params: Promise<{
    id: string;
  }>;
};

export default function ContractWorkspace({ params }: Props) {
  const resolvedParams = use(params);
  const contractId = resolvedParams.id;
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [sessionUser, setSessionUser] = useState<any>(null);
  const [userRole, setUserRole] = useState<"maker" | "employer">("maker");

  // Mock contract data for UI scaffolding
  const [contract, setContract] = useState({
    id: contractId,
    title: "Plumbing Fixes at Site B",
    description: "Fixing the main pipeline leak and installing 3 new copper fixtures as discussed on site.",
    price: 3500,
    status: "active", // "active", "completed", "disputed"
    employer_id: "emp_123",
    employer_name: "Dlamini Construction",
    maker_id: "mak_456",
    maker_name: "Siya The Plumber",
    escrow_funded: true,
    due_date: new Date(Date.now() + 3 * 86400000).toLocaleDateString(),
    review_submitted: false
  });

  const [isProcessing, setIsProcessing] = useState(false);
  const [reviewScore, setReviewScore] = useState(5);
  const [reviewNote, setReviewNote] = useState("");

  useEffect(() => {
    async function init() {
      const supabase = createClient();
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) { router.replace("/login"); return; }

      setSessionUser(user);

      const { data: profile } = await supabase.from('profiles').select('role').eq('id', user.id).single();
      if ((profile as any)?.role === "employer") setUserRole("employer");

      // Fetch Real Contract Data
      try {
        const { data: contractData } = await (supabase
          .from('contracts')
          .select('*')
          .eq('id', contractId)
          .single() as any);

        if (contractData) setContract(prev => ({ ...prev, ...contractData }));
      } catch (err) {
        console.log("Using local state for demo if not in DB.");
      }

      setLoading(false);
    }
    init();
  }, [router, contractId]);

  const handleReleaseFunds = async () => {
    if(!confirm("Are you sure you want to release Escrow funds? This is permanent and indicates you are satisfied with the work.")) return;

    setIsProcessing(true);
    const supabase = createClient();

    try {
       const { error } = await (supabase
         .from('contracts') as any)
         .update({ status: 'completed' })
         .eq('id', contractId);

       if (error) throw error;
       setContract(prev => ({ ...prev, status: "completed" }));
       alert("Funds released to Maker! 🇿🇦");
    } catch (err: any) {
       alert("Failed: " + err.message);
    } finally {
       setIsProcessing(false);
    }
  };

  const handleSubmitReview = async () => {
    if (!reviewNote.trim()) { alert("Please write a quick comment."); return; }

    setIsProcessing(true);
    try {
       await submitReview({
          maker_id: contract.maker_id,
          reviewer_id: sessionUser.id,
          rating: reviewScore,
          comment: reviewNote
       });
       setContract(prev => ({ ...prev, review_submitted: true }));
       alert("Vouch saved! 🇿🇦");
    } catch (err: any) {
       alert("Review Error: " + err.message);
    } finally {
       setIsProcessing(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-[#0D110F] flex items-center justify-center text-[#13EC6A] font-black italic tracking-widest text-2xl">
        LOADING WORKSPACE...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-transparent text-white font-sans selection:bg-[#13EC6A] selection:text-black p-8 lg:p-24 pb-40 relative overflow-hidden">
       <div className="max-w-6xl mx-auto space-y-24 relative z-10">

          {/* Header */}
          <div className="flex flex-col md:flex-row justify-between items-end border-b border-white/5 pb-16 gap-12">
             <div className="flex-1">
                <p className="text-[10px] font-black tracking-[0.5em] uppercase text-[#13EC6A] mb-8 italic drop-shadow-glow bg-[#13EC6A]/5 px-6 py-2 rounded-full border border-[#13EC6A]/20 inline-block">SECURE ESCROW PROTOCOL</p>
                <h1 className="text-7xl lg:text-8xl font-black italic tracking-tighter uppercase font-display leading-none text-glow">
                   {contract.title}
                </h1>
                <div className="flex items-center gap-8 mt-10">
                  <div className="flex items-center gap-3 text-gray-500 font-bold uppercase tracking-[0.3em] text-[10px] italic">
                    <span className="w-5 h-5 rounded-lg bg-white/5 flex items-center justify-center"><User size={12} /></span>
                    WITH {userRole === "employer" ? contract.maker_name : contract.employer_name}
                  </div>
                  <div className="w-px h-6 bg-white/10" />
                  <div className="flex items-center gap-3 text-gray-700 font-bold uppercase tracking-[0.3em] text-[10px] italic">
                    <span className="w-5 h-5 rounded-lg bg-white/5 flex items-center justify-center"><Clock size={12} /></span>
                    DUE {contract.due_date}
                  </div>
                </div>
             </div>

             <div className="flex items-center gap-4">
                <div className={`px-10 py-5 rounded-[2rem] text-[11px] uppercase font-black tracking-[0.3em] border italic shadow-premium ${
                  contract.status === "active" ? "bg-amber-500/10 text-amber-500 border-amber-500/20" :
                  contract.status === "completed" ? "bg-[#13EC6A]/10 text-[#13EC6A] border-[#13EC6A]/20 shadow-glow" :
                  "bg-red-500/10 text-red-500 border-red-500/20"
                }`}>
                  {contract.status === "active" ? "FUNDS LOCKED IN ESCROW" : contract.status.toUpperCase()}
                </div>
             </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">

             {/* Left Col - Details & Actions */}
             <div className="lg:col-span-8 space-y-12">

                {/* Status Banners */}
                {contract.status === "completed" && !contract.review_submitted && (
                   <div className="glass-card p-12 rounded-[4rem] border-2 border-indigo-500/30 bg-indigo-500/5 flex flex-col md:flex-row items-center gap-10 animate-in zoom-in duration-700">
                      <div className="w-24 h-24 rounded-[2.5rem] bg-indigo-500 text-white flex items-center justify-center shrink-0 shadow-[0_0_50px_rgba(99,102,241,0.3)] animate-pulse">
                         <Star size={48} fill="currentColor" />
                      </div>
                      <div className="flex-1 text-center md:text-left">
                         <h3 className="text-4xl font-black italic uppercase tracking-tighter text-indigo-400 font-display">Mission Complete.</h3>
                         <p className="text-[10px] font-black text-gray-500 mt-4 tracking-[0.3em] uppercase italic">Close the loop: Leave a mandatory vouch to sync reputation.</p>
                      </div>
                   </div>
                )}

                {/* Scope Box */}
                <div className="glass-card p-12 rounded-[4.5rem] border border-white/5 space-y-10 shadow-premium relative overflow-hidden group">
                   <div className="absolute top-0 right-0 p-12 text-white/5 opacity-0 group-hover:opacity-100 transition-opacity duration-1000">
                     <FileText size={160} />
                   </div>
                   <div className="flex items-center gap-6 mb-4">
                      <div className="w-12 h-12 rounded-2xl bg-white/5 flex items-center justify-center text-gray-500">
                        <FileText size={24} />
                      </div>
                      <h3 className="text-2xl font-black italic tracking-tighter uppercase font-display">Scope of Operation</h3>
                   </div>
                   <p className="text-2xl font-bold text-gray-400 italic leading-relaxed max-w-2xl px-2">
                      &quot;{contract.description}&quot;
                   </p>

                   <div className="grid grid-cols-1 md:grid-cols-2 gap-10 mt-12 bg-black/40 p-12 rounded-[3.5rem] border border-white/5 relative overflow-hidden">
                      <div className="flex flex-col gap-8">
                         <div>
                            <p className="text-[10px] text-gray-600 font-black uppercase tracking-[0.4em] mb-3 italic">EMPLOYER UNIT</p>
                            <p className="text-xl font-black italic font-display uppercase">{contract.employer_name}</p>
                         </div>
                         <div>
                            <p className="text-[10px] text-gray-600 font-black uppercase tracking-[0.4em] mb-3 italic">MAKER UNIT</p>
                            <p className="text-xl font-black italic font-display uppercase">{contract.maker_name}</p>
                         </div>
                      </div>

                      <div className="bg-[#13EC6A]/5 p-10 rounded-[2.5rem] border border-[#13EC6A]/10 space-y-6 shadow-premium">
                         <div className="flex justify-between items-center text-[10px]">
                            <span className="text-gray-500 font-black uppercase tracking-[0.3em] italic">GROSS PROTOCOL</span>
                            <span className="font-mono text-white/60">R{contract.price}</span>
                         </div>
                         <div className="flex justify-between items-center text-[10px]">
                            <span className="text-gray-500 font-black uppercase tracking-[0.3em] italic">SHAPA CORE FEE (10%)</span>
                            <span className="font-mono text-indigo-400">-R{(contract.price * 0.1).toFixed(2)}</span>
                         </div>
                         <div className="h-px bg-white/5 w-full" />
                         <div className="flex justify-between items-end">
                            <span className="text-[11px] text-[#13EC6A] font-black uppercase tracking-[0.4em] italic mb-1">NET SYNC</span>
                            <span className="font-mono text-[#13EC6A] text-4xl font-black drop-shadow-glow">R{(contract.price * 0.9).toFixed(2)}</span>
                         </div>
                      </div>
                   </div>
                </div>

                {/* Interactive Action Area based on Role and Status */}
                <div className="glass-card p-16 rounded-[4.5rem] border border-white/5 relative overflow-hidden shadow-premium">

                   {/* Employer Views */}
                   {userRole === "employer" && contract.status === "active" && (
                      <div className="space-y-10 relative z-10 text-center">
                         <div className="w-24 h-24 bg-amber-500/10 text-amber-500 rounded-[2rem] flex items-center justify-center mx-auto mb-10 shadow-premium border border-amber-500/20 group hover:rotate-12 transition-transform">
                            <Lock size={40} className="animate-pulse" />
                         </div>
                         <h3 className="text-5xl font-black uppercase italic tracking-tighter font-display leading-none">SATISFIED WITH SYNC?</h3>
                         <p className="text-sm font-bold text-gray-500 max-w-sm mx-auto leading-relaxed italic">Only release funds once the operational payload is fully delivered and verified by your unit.</p>

                         <div className="flex flex-col sm:flex-row gap-6 justify-center pt-8">
                            <button 
                               onClick={handleReleaseFunds}
                               disabled={isProcessing}
                               className="px-12 py-7 bg-[#13EC6A] text-[#052210] rounded-[2rem] font-black text-xs uppercase tracking-[0.4em] hover:scale-105 active:scale-95 transition-all shadow-glow flex items-center justify-center gap-4 italic border-b-8 border-black/10 group shimmer-border"
                            >
                               {isProcessing ? "PROCESSING..." : <><CheckCircle2 size={24} strokeWidth={3} /> RELEASE R{contract.price} TO MAKER</>}
                            </button>
                            <Link href="/support" className="px-10 py-7 glass-card border border-red-500/20 text-red-500/50 rounded-[2rem] font-black text-xs uppercase tracking-[0.4em] hover:bg-red-500/5 hover:text-red-500 transition-all flex items-center justify-center gap-4 italic hover:border-red-500/40">
                               <ShieldAlert size={20} /> OPEN DISPUTE
                            </Link>
                         </div>
                      </div>
                   )}

                   {/* Talent Views */}
                   {userRole === "maker" && contract.status === "active" && (
                      <div className="space-y-10 relative z-10 text-center">
                         <div className="w-24 h-24 bg-[#13EC6A]/10 text-[#13EC6A] rounded-[2.5rem] flex items-center justify-center mx-auto mb-10 shadow-glow border border-[#13EC6A]/20 group hover:rotate-12 transition-transform">
                            <Lock size={40} className="animate-pulse" />
                         </div>
                         <h3 className="text-6xl font-black uppercase italic tracking-tighter font-display leading-none text-glow">TIME TO HUSTLE.</h3>
                         <p className="text-[12px] font-black text-gray-600 max-w-sm mx-auto leading-relaxed italic uppercase tracking-[0.2em]">
                            R{contract.price} IS LOCKED IN SHAPA ESCROW. RELOAD YOUR PROGRESS AND SYNC WITH CLIENT FOR RELEASE.
                         </p>

                         <div className="pt-10 flex justify-center">
                            <Link href="/messages" className="inline-flex items-center gap-6 px-12 py-7 bg-white text-black rounded-[2rem] font-black uppercase tracking-[0.4em] text-[11px] hover:scale-110 active:scale-95 transition-all shadow-premium italic border-b-8 border-black/10">
                               <Briefcase size={20} strokeWidth={3} /> BROADCAST TO CLIENT
                            </Link>
                         </div>
                      </div>
                   )}

                   {/* Post-Completion Review Step (Both Roles) */}
                   {contract.status === "completed" && !contract.review_submitted && (
                      <div className="space-y-12 relative z-10">
                         <div className="flex items-center gap-6 mb-12 border-b border-white/5 pb-8">
                            <h3 className="text-6xl font-black uppercase italic tracking-tighter font-display text-glow">LEAVE A VOUCH</h3>
                         </div>

                         <div className="flex gap-6 justify-center">
                            {[1,2,3,4,5].map((star) => (
                               <button 
                                 key={star}
                                 onClick={() => setReviewScore(star)}
                                 className="hover:scale-125 transition-all hover:rotate-12 active:scale-90"
                               >
                                  <Star size={64} className={star <= reviewScore ? "text-amber-400 drop-shadow-glow" : "text-gray-800"} fill={star <= reviewScore ? "currentColor" : "none"} strokeWidth={1.5} />
                               </button>
                            ))}
                         </div>

                         <textarea 
                           placeholder={userRole === "employer" ? "HOW WAS THEIR OPS PERFORMANCE?" : "HOW WAS THIS CLIENTS PROTOCOL?"}
                           className="w-full bg-white/[0.03] border border-white/5 rounded-[3rem] p-10 h-48 text-xl focus:border-[#13EC6A]/30 transition-all focus:bg-white/[0.05] outline-none font-bold italic resize-none placeholder:text-gray-700 shadow-premium"
                           value={reviewNote}
                           onChange={e => setReviewNote(e.target.value)}
                         />

                         <button 
                           onClick={handleSubmitReview}
                           disabled={isProcessing}
                           className="w-full py-10 bg-indigo-600 text-white rounded-[2.5rem] font-black text-xs uppercase tracking-[0.5em] hover:scale-[1.02] active:scale-95 transition-all shadow-glow flex justify-center items-center gap-6 italic border-b-8 border-black/20 shimmer-border"
                         >
                            {isProcessing ? "SYNCING..." : <><Send size={24} strokeWidth={3} /> PUBLISH VOUCH TO PROFILE</>}
                         </button>
                      </div>
                   )}

                   {/* Fully Done State */}
                   {contract.status === "completed" && contract.review_submitted && (
                      <div className="text-center py-16">
                         <div className="w-32 h-32 bg-[#13EC6A] text-[#052210] rounded-[3rem] flex items-center justify-center mx-auto mb-10 shadow-[0_0_100px_rgba(19,236,106,0.3)] animate-in zoom-in duration-1000">
                            <CheckCircle2 size={72} strokeWidth={3} />
                         </div>
                         <h3 className="text-7xl font-black uppercase italic tracking-tighter font-display mb-6 text-glow">IT&apos;S A WRAP.</h3>
                         <p className="text-[11px] font-black text-gray-600 max-w-xs mx-auto uppercase tracking-[0.4em] italic leading-loose">PROTOCOL CLOSED. FUNDS RELEASED. REPUTATION SYNCED.</p>
                      </div>
                   )}
                </div>
             </div>

             {/* Right Col - Money & Safety */}
             <div className="lg:col-span-4 space-y-8">
                <div className="bg-[#050706] border border-[#13EC6A]/30 p-12 rounded-[4rem] relative overflow-hidden group shadow-premium">
                   <div className="absolute top-0 right-0 w-64 h-64 bg-[#13EC6A]/5 rounded-full blur-[100px] pointer-events-none" />
                   <DollarSign size={48} className="text-[#13EC6A] mb-10 drop-shadow-glow" />
                   <p className="text-[10px] font-black uppercase tracking-[0.4em] text-[#13EC6A] mb-4 italic opacity-80">PROTECTED ASSET VALUE</p>
                   <h4 className="text-7xl font-black font-display italic tracking-tighter text-glow leading-none mb-12">R{contract.price}</h4>

                   <div className="space-y-8 border-t border-white/5 pt-10">
                      <div className="flex justify-between items-center px-2">
                         <p className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em] italic">PLATFORM PROTOCOL FEE</p>
                         <p className="font-bold text-red-500 font-mono italic"> -R{(contract.price * 0.1).toFixed(0)}</p>
                      </div>
                      <div className="p-8 bg-white/[0.02] rounded-[2rem] border border-[#13EC6A]/10 shadow-premium">
                         <p className="text-[10px] font-black text-[#13EC6A] uppercase tracking-[0.4em] mb-4 italic">MAKER SYNC PAYOUT</p>
                         <p className="text-4xl font-black text-white font-display italic tracking-tighter"> R{(contract.price * 0.9).toFixed(0)}</p>
                      </div>
