"use client";

import { useEffect, useState, useRef } from "react";
import { Play, Search, Zap, MapPin, Heart, MessageCircle, Share2, User } from "lucide-react";
import { createClient } from "@/utils/supabase/client";
import { VerificationBadge, VerificationTier } from "@/components/VerificationBadge";
import { vouchForMaker } from "@/lib/actions/verification";
import { createConversation } from "@/lib/actions/messages";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { FeaturedBadge } from "@/components/FeaturedBadge";

interface ProofWithMaker {
  id: string;
  video_url: string;
  title: string;
  maker_id: string;
  makers: {
    id: string;
    name: string;
    trade: string;
    location: string;
    verification_tier: string;
    reliability_score: number;
    featured_until?: string;
  } | null;
}

export default function DiscoveryPage() {
  const [proofs, setProofs] = useState<ProofWithMaker[]>([]);
  const [loading, setLoading] = useState(true);
  const containerRef = useRef<HTMLDivElement>(null);

  const [userCoords, setUserCoords] = useState<{lat: number, lng: number} | null>(null);

  useEffect(() => {
    // 1. Get User Location
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition(
        (pos) => setUserCoords({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
        (err) => console.log("Location denied. Falling back to default.")
      );
    }

    async function fetchProofs() {
      const supabase = createClient();
      const { data, error } = await supabase
        .from("proofs")
        .select(`
          id, video_url, title, maker_id,
          makers:public_makers!maker_id (id, name, trade, location, verification_tier, reliability_score, featured_until, latitude, longitude)
        `)
        .order("created_at", { ascending: false });

      if (data) {
        let sorted = [...(data as any)];

        // 2. Proximity Sorting (if user location available)
        if (userCoords) {
           sorted = sorted.sort((a, b) => {
              const distA = a.makers?.latitude ? Math.sqrt(Math.pow(a.makers.latitude - userCoords.lat, 2) + Math.pow(a.makers.longitude - userCoords.lng, 2)) : 999;
              const distB = b.makers?.latitude ? Math.sqrt(Math.pow(b.makers.latitude - userCoords.lat, 2) + Math.pow(b.makers.longitude - userCoords.lng, 2)) : 999;
              return distA - distB;
           });
        }

        // 3. Featured Boost (Primary Sort)
        sorted = sorted.sort((a: any, b: any) => {
          const aFeatured = a.makers?.featured_until && new Date(a.makers.featured_until) > new Date();
          const bFeatured = b.makers?.featured_until && new Date(b.makers.featured_until) > new Date();
          if (aFeatured && !bFeatured) return -1;
          if (!aFeatured && bFeatured) return 1;
          return 0;
        });
        setProofs(sorted);
      }
      setLoading(false);
    }
    fetchProofs();
  }, [userCoords]); // Refetch when location updates

  const handleUpdateMaker = (makerId: string, newScore: number, newTier: string) => {
    setProofs(prev => prev.map(p => {
      if (p.makers?.id === makerId) {
        return {
          ...p,
          makers: {
            ...p.makers,
            reliability_score: newScore,
            verification_tier: newTier
          }
        };
      }
      return p;
    }));
  };

  if (loading) {
    return (
      <div className="h-screen bg-black flex items-center justify-center">
        <Zap className="animate-pulse text-[#13EC6A]" size={48} />
      </div>
    );
  }

  return (
    <div className="h-screen bg-black overflow-hidden relative">
      {/* Search Header Overlay */}
      <div className="absolute top-0 inset-x-0 p-8 z-30 flex justify-between items-center pointer-events-none">
        <h1 className="text-3xl font-black italic tracking-tighter font-display text-white drop-shadow-glow pointer-events-auto">Discovery.</h1>
        <button className="w-12 h-12 glass rounded-2xl flex items-center justify-center border border-white/10 pointer-events-auto text-white">
          <Search size={24} />
        </button>
      </div>

      <div 
        ref={containerRef}
        className="h-full overflow-y-scroll snap-y snap-mandatory scrollbar-hide"
      >
        {proofs.length > 0 ? (
          proofs.map((proof) => (
            <VideoCard key={proof.id} proof={proof} onUpdateMaker={handleUpdateMaker} />
          ))
        ) : (
          <div className="h-full flex flex-col items-center justify-center p-12 text-center text-gray-500">
             <Zap size={64} className="mb-8 opacity-20" />
             <p className="text-xl font-bold italic mb-4">No VibeCheck clips found in your hood.</p>
             <p className="text-xs uppercase tracking-widest font-black">Be the first to record one!</p>
          </div>
        )}
      </div>
    </div>
  );
}

function VideoCard({ proof, onUpdateMaker }: { proof: ProofWithMaker, onUpdateMaker: (id: string, score: number, tier: string) => void }) {
  const router = useRouter();
  const videoRef = useRef<HTMLVideoElement>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isVouching, setIsVouching] = useState(false);
  const [vouched, setVouched] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    // 1. Playback Observer (Active)
    const playObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          video.play().catch(() => {});
          setIsPlaying(true);
        } else {
          video.pause();
          setIsPlaying(false);
        }
      });
    }, { threshold: 0.6 });

    // 2. Preload Observer (Passive)
    const preloadObserver = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          // Preload the video when it's 20% visible or nearby
          video.preload = "auto";
        }
      });
    }, { threshold: 0.1 });

    playObserver.observe(video);
    preloadObserver.observe(video);

    return () => {
      playObserver.disconnect();
      preloadObserver.disconnect();
    };
  }, []);

  const handleVouch = async () => {
    if (vouched || isVouching || !proof.makers?.id) return;

    setIsVouching(true);
    try {
      const { newScore, newTier } = await vouchForMaker(proof.makers.id);
      onUpdateMaker(proof.makers.id, newScore, newTier);
      setVouched(true);
    } catch (err) {
      console.error("Vouch error:", err);
    } finally {
      setIsVouching(false);
    }
  };

  const handleHustle = async () => {
    if (!proof.makers?.id) return;
    try {
      const conv = await createConversation(proof.makers.id);
      router.push(`/messages/${(conv as any).id}`);
    } catch (err) {
      console.error("Hustle error:", err);
      alert("Could not start conversation. Please try again.");
    }
  };

  return (
    <div className="h-full w-full snap-start relative bg-black flex items-center justify-center">
      {/* Video element */}
      <video 
        ref={videoRef}
        src={proof.video_url}
        className="h-full w-full object-cover"
        loop
        muted
        playsInline
      />

      {/* Play/Pause Overlay Toggle */}
      <div 
        className="absolute inset-0 z-10 flex items-center justify-center"
        onClick={() => {
          if (videoRef.current?.paused) {
            videoRef.current.play().catch(() => {});
            setIsPlaying(true);
          } else {
            videoRef.current?.pause();
            setIsPlaying(false);
          }
        }}
      >
        {!isPlaying && <Play fill="white" size={64} className="text-white opacity-40" />}
      </div>

      {/* Interactions Overlay */}
      <div className="absolute right-6 bottom-32 flex flex-col gap-8 z-20">
         <div className="flex flex-col items-center gap-2 group">
           <button 
             onClick={handleVouch}
             disabled={vouched || isVouching}
             className={`w-14 h-14 glass rounded-full flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all active:scale-90 ${vouched ? 'text-red-500 bg-red-500/10' : 'text-white'}`}
           >
             <Heart size={28} fill={vouched ? "currentColor" : "none"} className={`${vouched ? 'text-red-500' : 'group-hover:text-red-500'} transition-colors ${isVouching ? 'animate-pulse' : ''}`} />
           </button>
           <span className="text-[10px] font-black italic">{vouched ? 'Vouched' : 'Vouch'}</span>
         </div>
         <div className="flex flex-col items-center gap-2">
           <button 
             onClick={handleHustle}
             className="w-14 h-14 glass rounded-full flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all text-white"
           >
             <MessageCircle size={28} />
           </button>
           <span className="text-[10px] font-black italic">Hustle</span>
         </div>
         <div className="flex flex-col items-center gap-2">
           <button className="w-14 h-14 glass rounded-full flex items-center justify-center border border-white/5 hover:bg-white/10 transition-all text-white">
             <Share2 size={28} />
           </button>
           <span className="text-[10px] font-black italic">Share</span>
         </div>
      </div>

      {/* Info Overlay */}
      <div className="absolute bottom-0 inset-x-0 p-10 bg-gradient-to-t from-black via-black/40 to-transparent z-20 flex justify-between items-end">
         <div className="space-y-4 max-w-[70%] text-white">
            <div className="flex items-center gap-3">
               <Link href={`/u/${proof.makers?.id}`} className="w-12 h-12 rounded-full glass border-2 border-[#13EC6A] flex items-center justify-center hover:scale-110 transition-transform">
                  <User size={24} />
               </Link>
               <div className="space-y-2">
                  <div className="flex items-center gap-3">
                    <Link href={`/u/${proof.makers?.id}`} className="hover:text-[#13EC6A] transition-colors">
                       <h3 className="text-xl font-black tracking-tighter italic font-display">@{proof.makers?.name || 'Anonymous'}</h3>
                    </Link>
                    <VerificationBadge 
                      tier={(proof.makers?.verification_tier as VerificationTier) || 'basic'} 
                      score={proof.makers?.reliability_score}
                    />
                    {proof.makers?.featured_until && new Date(proof.makers.featured_until) > new Date() && (
                      <FeaturedBadge />
                    )}
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-widest text-[#13EC6A] flex items-center gap-1">
                     <Zap size={10} fill="currentColor" /> {proof.makers?.trade || 'Skillful Artisan'}
                  </p>
               </div>
            </div>
            <p className="font-bold text-sm leading-relaxed opacity-90">{proof.title || "Checking in from the hood. Shapa!"}</p>
            <div className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-gray-500">
               <MapPin size={12} className="text-[#13EC6A]" /> {proof.makers?.location || 'South Africa'}
            </div>
         </div>
      </div>
    </div>
  );
}

"use client";
