export default function ContractManager() {
  const [contracts, setContracts] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [user, setUser] = useState<any>(null);
  const [releasingId, setReleasingId] = useState<string | null>(null);

  // Review Modal State
  const [reviewTarget, setReviewTarget] = useState<{makerId: string, makerName: string, contractId: string} | null>(null);

  useEffect(() => {
    const supabase = createClient();
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session: any) => setUser(session?.user ?? null));
    return () => subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      loadContracts();
    }
  }, [user]);

  async function loadContracts() {
    setIsLoading(true);
    try {
      const data = await contractsHub.fetchByEmployer(user.id);
      setContracts(data);
    } catch (err) {
      console.error("Failed to load contracts:", err);
    } finally {
      setIsLoading(false);
    }
  }

  const handleReleaseFunds = async (contract: any) => {
    if (!confirm(`Are you sure you want to release R${contract.price} to ${contract.makers.name}?`)) return;

    setReleasingId(contract.id);
    try {
      const supabase = createClient();

      // 1. Update Contract
      await contractsHub.update(contract.id, { status: 'completed' });

      // 2. Wallet Logic (Maker)
      const { data: wallet } = await supabase.from('wallets').select('*').eq('user_id', contract.maker_id).single() as { data: any };

      if (wallet) {
        const newBalance = Number(wallet.balance) + Number(contract.price);
        const newPending = Number(wallet.pending_balance) - Number(contract.price);

        await (supabase.from('wallets') as any).update({ 
          balance: newBalance, 
          pending_balance: newPending,
          updated_at: new Date().toISOString()
        }).eq('id', wallet.id);

        // 3. Log Transaction
        await (supabase.from('transactions') as any).insert({
          wallet_id: wallet.id,
          type: 'credit',
          amount: contract.price,
          description: `Funds released for contract: ${contract.title}`,
          status: 'completed'
        });
      }

      // 4. Update UI
      setContracts(prev => prev.map(c => c.id === contract.id ? { ...c, status: 'completed' } : c));

      // 5. Open Review
      setReviewTarget({
        makerId: contract.maker_id,
        makerName: contract.makers.name,
        contractId: contract.id
      });

    } catch (err) {
      console.error("Fund release failed:", err);
      alert("Encountered an error during fund release. Please check your connection.");
    } finally {
      setReleasingId(null);
    }
  };

  return (
    <div className="min-h-screen bg-transparent text-white font-sans">
