      const { data: employerData } = await supabase.from('profiles').select('*').eq('id', user.id).single();
      setEmployer(employerData);

      const { data: makerData } = await supabase.from('profiles').select('*').eq('id', makerId).single();
      setMaker(makerData);

      setLoading(false);
    }
    init();
  }, [makerId, router]);

  const handleCreateContract = async () => {
    setSubmitting(true);
    const supabase = createClient();

    try {
      // In a full DB, we'd insert into a `contracts` table. 
      // For this MVP, we simulate it by using the `gigs` table but marked internal/private, or a mock action
      // We'll mock the contract generation for the demo

      const newContractId = `C-${Math.floor(Math.random() * 1000000)}`;
      setContractId(newContractId);

      // Simulate network delay for "locking funds into Escrow"
      await new Promise(resolve => setTimeout(resolve, 2000));

      setStep("success");
    } catch (err) {
      alert("Failed to create contract.");
    } finally {
      setSubmitting(false);
    }
