  identity_verified: boolean;
  phone?: string;
  created_at: string;
  featured_until?: string;
  proofs: { title: string; created_at: string }[];
};

interface HubClientProps {
  initialMakers: Maker[];
  initialJobs: any[];
  initialSavedIds: string[];
  userId: string | null;
}

export default function HubClient({ initialMakers, initialJobs, initialSavedIds, userId }: HubClientProps) {
  const router = useRouter();
  const [makers] = useState<Maker[]>(initialMakers);
  const [query, setQuery] = useState("");
  const [savedIds, setSavedIds] = useState<Set<string>>(new Set(initialSavedIds));
  const [myJobs] = useState<any[]>(initialJobs);

  const toggleSave = useCallback(async (makerId: string) => {
    if (!userId) {
      router.push("/login?returnTo=/employer/hub");
      return;
    }

    try {
      await savedMakersHub.upsert(userId, makerId);
      setSavedIds(prev => {
        const next = new Set(prev);
        if (next.has(makerId)) next.delete(makerId);
        else next.add(makerId);
        return next;
      });
    } catch (err) {
      console.error("Error toggling save:", err);
    }
  }, [userId, router]);

  const [now] = useState(() => Date.now());

  const filtered = makers.filter((m: Maker) => {
    if (!query.trim()) return true;

    if (query === "First Gigs") {
       const isNew = new Date(m.created_at).getTime() > now - 30 * 24 * 60 * 60 * 1000;
       return isNew;
    }

    const { skill, location } = parseSmartSearch(query);

    const matchesSkill = !skill || 
      m.trade?.toLowerCase().includes(skill) || 
      m.name?.toLowerCase().includes(skill);

    const matchesLocation = !location || 
      m.location?.toLowerCase().includes(location);

    return matchesSkill && matchesLocation;
  }).sort((a, b) => {
    const aFeatured = a.featured_until && new Date(a.featured_until) > new Date();
    const bFeatured = b.featured_until && new Date(b.featured_until) > new Date();
    if (aFeatured && !bFeatured) return -1;
    if (!aFeatured && bFeatured) return 1;
    return 0;
