                  <MakerCard
                    key={maker.id}
                    maker={maker}
                    isSaved={savedIds.has(maker.id)}
                    onSave={() => toggleSave(maker.id)}
                  />
                ))
              ) : (
                <div className="col-span-full py-32 text-center glass-card rounded-[4rem] border border-dashed border-white/10">
                   <div className="w-24 h-24 bg-white/5 rounded-[2rem] flex items-center justify-center mx-auto mb-10 text-gray-700">
