import { createClient } from "@/utils/supabase/server";
import { makersHub, jobsHub } from "@/lib/supabase-helpers";
import HubClient from "./HubClient";

export default async function EmployerHubPage() {
  const supabase = await createClient();
  const { data: { session } } = await supabase.auth.getSession();
  const user = session?.user ?? null;

  // Fetch initial makers (public data)
  const makers = await makersHub.fetchAll(supabase);

  let initialJobs: any[] = [];
  let initialSavedIds: string[] = [];

  if (user) {
    // Fetch employer's jobs
    initialJobs = await jobsHub.fetchForEmployer(user.id, supabase);

    // Fetch saved makers IDs
    const { data: savedData } = await supabase
      .from('saved_makers')
      .select('maker_id')
      .eq('user_id', user.id);

    initialSavedIds = (savedData as any[])?.map(s => s.maker_id) || [];
  }

  return (
    <HubClient 
      initialMakers={makers as any}
      initialJobs={initialJobs}
      initialSavedIds={initialSavedIds}
      userId={user?.id ?? null}
    />
  );
}

