import { Search, MapPin, Clock, Gem, ArrowUpRight, List, Map as MapIcon, Zap } from "lucide-react";
import WorkRadar from "@/components/WorkRadar";
import { getDistance, getCoordsForLocation } from "@/lib/locationUtils";
import { useGeolocation } from "@/hooks/useGeolocation";

type Job = {
  id: string;
  title: string;
  trade: string;
  location: string;
  description: string;
  budget: string;
  created_at: string;
};

export default function GigBoard() {
  const supabase = createClient();
  const [jobs, setJobs] = useState<Job[]>([]);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [viewMode, setViewMode] = useState<"list" | "map">("list");
  const [activeRadius, setActiveRadius] = useState<number | null>(null);
  const { latitude, longitude } = useGeolocation();
  const [now] = useState(() => Date.now());

  useEffect(() => {
    async function load() {
      setLoading(true);
      const { data } = await supabase
        .from("jobs")
        .select("*")
        .eq("status", "open")
        .order("created_at", { ascending: false });

      setJobs(data || []);
      setLoading(false);
    }
    load();
  }, []);

  const filtered = jobs.filter(j => {
    const matchesQuery = 
      j.title.toLowerCase().includes(query.toLowerCase()) ||
      j.trade.toLowerCase().includes(query.toLowerCase()) ||
      j.location.toLowerCase().includes(query.toLowerCase());

    if (!activeRadius || !latitude || !longitude) return matchesQuery;

    const jobCoords = getCoordsForLocation(j.location);
    if (!jobCoords) return matchesQuery;

    const distance = getDistance(latitude, longitude, jobCoords.lat, jobCoords.lng);
    return matchesQuery && distance <= activeRadius;
  });

  return (
    <div className="min-h-screen bg-[#111613] text-white font-sans">
