                            <MapPin size={18} className="text-gray-600 group-hover/card:text-[#13EC6A] transition-colors" />
                         </div>
                         <h4 className="font-black text-2xl mb-2 truncate italic font-display tracking-tight leading-tight">{job.title}</h4>
                         <p className="text-[10px] text-gray-500 font-black uppercase tracking-widest truncate"><span className="text-[#13EC6A] drop-shadow-glow">Budget: {job.budget}</span> • {job.location}</p>
                      </Link>
                   ))}
                </div>
             </div>
          ) : filtered.length > 0 ? (
            <div className="grid grid-cols-1 gap-6">
