  );
}

function JobCard({ job, now }: { job: Job; now: number }) {
  const timeAgo = (dateStr: string) => {
    const diff = now - new Date(dateStr).getTime();
    const h = Math.floor(diff / 3_600_000);
    if (h < 1) return "Just now";
    if (h < 24) return `${h}h ago`;
    return `${Math.floor(h / 24)}d ago`;
  };

  return (
    <div className="group glass p-12 rounded-[3.5rem] border border-white/5 hover:border-[#13EC6A]/30 transition-all duration-700 cursor-pointer relative overflow-hidden shadow-premium font-body">
      {/* Glow effect on hover */}
      <div className="absolute top-0 right-0 w-64 h-64 bg-[#13EC6A]/5 rounded-full blur-[100px] opacity-0 group-hover:opacity-100 transition-opacity duration-1000" />

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-12 relative z-10">
        <div className="flex-1">
          <div className="flex items-center gap-6 mb-8">
            <span className="bg-[#13EC6A]/10 text-[#13EC6A] px-5 py-2 rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] border border-[#13EC6A]/20 shadow-glow italic">
               {job.trade}
            </span>
            <span className="text-gray-600 text-[10px] font-black uppercase tracking-[0.2em] flex items-center gap-3">
               <Clock size={14} className="text-gray-700" /> {timeAgo(job.created_at)}
            </span>
          </div>
          <h3 className="text-4xl font-black mb-8 tracking-tighter italic group-hover:text-[#13EC6A] transition-colors leading-[1.1] font-display">{job.title}</h3>
          <div className="flex flex-wrap gap-8 text-[10px] font-black uppercase tracking-[0.2em]">
            <span className="flex items-center gap-3 text-gray-500"><MapPin size={18} className="text-[#13EC6A]" /> {job.location}</span>
            {job.budget && <span className="flex items-center gap-3 text-[#13EC6A] drop-shadow-glow"><Zap size={18} fill="currentColor" /> {job.budget}</span>}
          </div>
        </div>

        <Link 
          href={`/gigs/${job.id}`}
          className="flex items-center gap-4 bg-white text-black px-12 py-6 rounded-[2rem] font-black text-[10px] uppercase tracking-[0.2em] hover:bg-[#13EC6A] hover:text-[#052210] transition-all group/btn shadow-premium self-start md:self-center border-b-4 border-gray-300 active:border-b-0 active:translate-y-1"
        >
          View & Apply <ArrowUpRight size={20} className="group-hover/btn:translate-x-1 group-hover/btn:-translate-y-1 transition-transform" />
        </Link>
      </div>
    </div>
  );
}

"use client";

import { Send, Plus, MoreVertical, ArrowLeft, Loader2, Video, X, Shield, Sparkles } from "lucide-react";
import Link from "next/link";
import { useState, useEffect, useRef, use } from "react";
import { createClient } from "@/utils/supabase/client";
import { sendMessage } from "@/lib/actions/messages";
import { maskPhoneNumbers } from "@/utils/privacy";

interface Message {
  id: string;
  sender_id: string;
  text: string;
  created_at: string;
}

export default function ConversationView({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const conversationId = resolvedParams.id;

  const [messages, setMessages] = useState<Message[]>([]);
  const [msg, setMsg] = useState("");
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);
  const [partner, setPartner] = useState<{ name: string; trade: string } | null>(null);
  const [showVibeCheck, setShowVibeCheck] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const supabase = createClient();

    async function fetchData() {
      // 1. Get current user
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;
      setUserId(user.id);

      // 2. Get conversation partner info
      const { data: conv } = await supabase
        .from('conversations')
        .select('user_1_id, user_2_id')
        .eq('id', conversationId)
        .single();

      if (conv) {
        const otherId = (conv as any).user_1_id === user.id ? (conv as any).user_2_id : (conv as any).user_1_id;

        // Try makers first (Talent)
        const { data: maker } = await supabase
          .from('makers')
          .select('name, trade')
          .eq('id', otherId)
          .maybeSingle();

        if (maker) {
          setPartner(maker as any);
        } else {
          // Fallback to profiles (Employer)
          const { data: profile } = await supabase
            .from('profiles')
            .select('name')
            .eq('id', otherId)
            .maybeSingle();

          if (profile) {
            setPartner({ name: (profile as any).name, trade: 'Employer' });
          }
        }
      }

      // 3. Initial message fetch
      const { data: msgs } = await supabase
        .from('messages')
        .select('*')
        .eq('conversation_id', conversationId)
        .order('created_at', { ascending: true });

      if (msgs) setMessages(msgs as any[]);
      setLoading(false);

      // Initial scroll
      setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: "smooth" }), 100);
    }

    fetchData();

    // 4. Subscribe to new messages
    const channel = supabase
      .channel(`chat:${conversationId}`)
      .on('postgres_changes', { 
        event: 'INSERT', 
        schema: 'public', 
        table: 'messages',
        filter: `conversation_id=eq.${conversationId}`
      }, (payload) => {
        setMessages(prev => [...prev, payload.new as Message]);
        setTimeout(() => scrollRef.current?.scrollIntoView({ behavior: "smooth" }), 50);
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [conversationId]);

  const handleSend = async () => {
    if (!msg.trim()) return;
    const currentMsg = msg;
    setMsg("");
    try {
      await sendMessage(conversationId, currentMsg);
    } catch (err) {
      console.error(err);
      alert("Failed to send message.");
      setMsg(currentMsg);
    }
  };

  if (loading) {
    return (
      <div className="flex-1 flex items-center justify-center">
        <Loader2 className="animate-spin text-[#13EC6A]" size={48} />
      </div>
    );
  }

  return (
    <div className="flex-1 flex flex-col h-full bg-transparent relative selection:bg-[#13EC6A]/30 mb-20">
      {/* Chat Header */}
      <header className="p-10 border-b border-white/5 backdrop-blur-3xl bg-black/40 flex items-center justify-between z-20 shadow-[0_20px_50px_rgba(0,0,0,0.5)]">
        <div className="flex items-center gap-8">
          <Link href="/messages" className="lg:hidden w-14 h-14 glass-card rounded-2xl flex items-center justify-center text-white hover:text-[#13EC6A] transition-colors">
            <ArrowLeft size={24} />
          </Link>
          <div className="relative group">
            <div className="w-16 h-16 rounded-[1.8rem] bg-[#13EC6A] flex items-center justify-center text-[#052210] font-black italic font-display shadow-glow group-hover:rotate-12 transition-all duration-500 text-2xl">
              {partner?.name?.[0] || "?"}
            </div>
            <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-[#13EC6A] rounded-full border-4 border-black animate-pulse" />
          </div>
          <div>
            <h2 className="text-3xl font-black italic tracking-tighter font-display uppercase leading-none mb-2">{partner?.name || "ANONYMOUS UNIT"}</h2>
            <div className="flex items-center gap-3">
              <p className="text-[10px] font-black uppercase tracking-[0.3em] text-[#13EC6A] italic opacity-80">{partner?.trade || "PROTOCOL ACTIVE"}</p>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-6">
          <button 
            onClick={() => setShowVibeCheck(true)}
            className="w-14 h-14 glass-card rounded-[1.2rem] flex items-center justify-center text-[#13EC6A] hover:bg-[#13EC6A]/10 transition-all shadow-glow hover:scale-110 active:scale-95 group"
            title="LAUNCH VIBE CHECK BRIDGE"
          >
            <Video size={24} className="group-hover:rotate-12 transition-transform" />
          </button>
          <button className="w-14 h-14 glass-card rounded-[1.2rem] flex items-center justify-center text-gray-600 hover:text-white transition-all hover:bg-white/5">
            <MoreVertical size={24} />
          </button>
        </div>
      </header>

      {/* Vibe Check UI - High Fidelity Bridge */}
      {showVibeCheck && (
        <div className="absolute inset-0 z-[100] bg-black/95 backdrop-blur-3xl flex items-center justify-center p-8 animate-in fade-in zoom-in-95 duration-700">
          <div className="max-w-2xl w-full glass-card p-16 rounded-[5rem] border border-[#13EC6A]/30 relative overflow-hidden text-center shadow-[0_0_150px_rgba(19,236,106,0.15)]">
            <div className="absolute top-0 right-0 p-16 text-[#13EC6A]/5 pointer-events-none">
              <Video size={400} />
            </div>

            <button 
              onClick={() => setShowVibeCheck(false)}
              className="absolute top-12 right-12 w-16 h-16 glass-card rounded-[1.5rem] flex items-center justify-center text-gray-500 hover:text-white transition-all hover:rotate-90 hover:bg-white/5"
            >
              <X size={28} />
            </button>

            <div className="w-32 h-32 rounded-[2.5rem] bg-[#13EC6A]/20 flex items-center justify-center text-[#13EC6A] mx-auto mb-12 shadow-glow animate-pulse border border-[#13EC6A]/30">
              <Shield size={64} />
            </div>

            <h3 className="text-7xl font-black italic tracking-tighter mb-8 font-display uppercase leading-none text-glow">Vibe Check.</h3>
            <p className="text-2xl text-gray-400 font-bold mb-16 leading-relaxed italic max-w-lg mx-auto">
