"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { Search, MessageSquare, Gem, Filter, Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { createClient } from "@/utils/supabase/client";

interface Conversation {
  id: string;
  last_message: string | null;
  updated_at: string;
  user_1_id: string;
  user_2_id: string;
  other_user?: {
    name: string;
    trade: string;
  };
}

export default function MessagesLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const isListOnly = pathname === "/messages";
  const [conversations, setConversations] = useState<Conversation[]>([]);
  const [loading, setLoading] = useState(true);
  const [userId, setUserId] = useState<string | null>(null);

  useEffect(() => {
    const supabase = createClient();

    async function init() {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;
      setUserId(user.id);

      // Fetch conversations
      const { data, error } = await supabase
        .from('conversations')
        .select(`
          *,
          user_1:user_1_id(id),
          user_2:user_2_id(id)
        `)
        .or(`user_1_id.eq.${user.id},user_2_id.eq.${user.id}`)
        .order('updated_at', { ascending: false });

      if (data) {
        // Hydrate with profile/maker info
        const hydrated = await Promise.all((data as any[]).map(async (conv) => {
          const otherId = conv.user_1_id === user.id ? conv.user_2_id : conv.user_1_id;
          const { data: maker } = await supabase
            .from('makers')
            .select('name, trade')
            .eq('id', otherId)
            .single();

          return {
            ...conv,
            other_user: maker || { name: "Anonymous", trade: "User" }
          } as Conversation;
        }));
        setConversations(hydrated);
      }
      setLoading(false);
    }
    init();

    // Real-time updates for conversation list
    const channel = supabase
      .channel('conversations_changes')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'conversations' }, () => {
        init();
      })
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  return (
    <div className="min-h-screen bg-transparent text-white font-sans flex overflow-hidden selection:bg-[#13EC6A]/30">
      {/* Conversation Sidebar */}
      <aside className={`w-full lg:w-[450px] border-r border-white/5 bg-black/40 backdrop-blur-3xl flex flex-col ${!isListOnly ? "hidden lg:flex" : "flex"} relative z-50 shadow-[40px_0_100px_rgba(0,0,0,0.5)]`}>
        <header className="p-12 space-y-10 border-b border-white/5 pb-16">
          <div className="flex items-center justify-between px-2">
            <div>
              <h1 className="text-6xl font-black italic tracking-tighter font-display text-glow uppercase leading-none">Inbox.</h1>
              <p className="text-[10px] font-black text-gray-600 uppercase tracking-[0.4em] italic mt-4">Safe & Secure Channel</p>
            </div>
            <div className="w-16 h-16 rounded-[2rem] bg-[#13EC6A]/5 border border-[#13EC6A]/20 flex items-center justify-center text-[#13EC6A] shadow-glow group hover:scale-110 transition-transform">
              <MessageSquare size={28} className="group-hover:rotate-12 transition-transform" />
            </div>
          </div>
          <div className="relative group px-2">
            <input 
              type="text" 
              placeholder="SEARCH PROTOCOLS..." 
              className="w-full bg-white/[0.03] border border-white/5 rounded-[2rem] px-8 py-6 outline-none focus:border-[#13EC6A]/40 focus:bg-white/[0.05] transition-all font-black uppercase tracking-[0.2em] text-[11px] italic placeholder:text-gray-700"
            />
            <Search size={22} className="absolute right-10 top-1/2 -translate-y-1/2 text-gray-700 group-focus-within:text-[#13EC6A] transition-colors" />
          </div>
        </header>

        <nav className="flex-1 overflow-y-auto px-6 py-10 hide-scrollbar">
          <div className="space-y-4">
            {loading ? (
              <div className="flex flex-col items-center justify-center p-32 space-y-4">
                <Loader2 className="animate-spin text-[#13EC6A] drop-shadow-glow" size={48} />
                <p className="text-[10px] font-black text-gray-700 uppercase tracking-[0.4em] animate-pulse">Syncing Cryptos...</p>
              </div>
            ) : conversations.length > 0 ? (
              conversations.map((chat) => (
                <Link 
                  key={chat.id}
                  href={`/messages/${chat.id}`}
                  className={`flex items-center gap-6 p-8 rounded-[2.5rem] transition-all duration-500 group border border-transparent relative overflow-hidden ${
                    pathname.includes(`/messages/${chat.id}`) 
                      ? "bg-[#13EC6A] text-[#052210] shadow-glow scale-[1.02]" 
                      : "hover:bg-white/5 hover:border-white/5"
                  }`}
                >
                  <div className={`w-16 h-16 rounded-[1.8rem] flex items-center justify-center text-2xl font-black font-display flex-shrink-0 transition-transform group-hover:rotate-12 ${
                    pathname.includes(`/messages/${chat.id}`) ? "bg-black/20 text-[#052210]" : "bg-white/5 text-gray-500"
                  }`}>
                    {chat.other_user?.name[0]}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex justify-between items-center mb-2">
                      <h3 className="font-black italic text-lg tracking-tight truncate font-display uppercase group-hover:text-current">{chat.other_user?.name}</h3>
                      <span className={`text-[9px] font-black uppercase tracking-widest italic ${
                        pathname.includes(`/messages/${chat.id}`) ? "text-[#052210]/40" : "text-gray-600"
                      }`}>
                        {new Date(chat.updated_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                      </span>
                    </div>
                    <p className={`text-[10px] font-bold truncate leading-relaxed italic ${
                      pathname.includes(`/messages/${chat.id}`) ? "text-[#052210]/60" : "text-gray-500"
                    }`}>{chat.last_message || "ESTABLISHING LINK..."}</p>
                  </div>
                </Link>
              )
            )) : (
              <div className="text-center p-20 space-y-8 opacity-20">
                <div className="w-24 h-24 rounded-[3rem] bg-white/5 flex items-center justify-center mx-auto">
                    <MessageSquare size={48} className="text-gray-400" />
                </div>
                <h4 className="font-black italic tracking-[0.2em] font-display uppercase text-2xl">Void Channel.</h4>
                <p className="text-[10px] uppercase font-black tracking-[0.4em]">Establish your first connection</p>
              </div>
            )}
          </div>
        </nav>
      </aside>

      {/* Main Chat Area */}
      <main className={`flex-1 relative flex flex-col ${isListOnly ? "hidden lg:flex" : "flex"} bg-black/10`}>
        <div className="absolute inset-0 bg-gradient-to-br from-[#13EC6A]/5 to-transparent pointer-events-none opacity-40 blur-[100px]" />
        <div className="relative z-10 w-full h-full">
          {children}
        </div>
      </main>
    </div>
  );
}

