export default function SettingsPage() {
  const router = useRouter();
  const supabase = createClient();
  const [activeTab, setActiveTab] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [profile, setProfile] = useState<any>(null);

  useEffect(() => {
    const fetchProfile = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const { data } = await supabase
        .from('profiles')
        .select('*')
        .eq('id', user.id)
        .single();
      setProfile(data);
    };
    fetchProfile();
  }, []);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    router.push("/login");
  };

  const sections = [
    { id: "account", title: "Account", icon: User, desc: "Bio, Profile Energy, VibeCV" },
    { id: "privacy", title: "Privacy", icon: Shield, desc: "Radar, Visibility, Blocking" },
    { id: "alerts", title: "Alerts", icon: Bell, desc: "Gigs, Messages, Activity" },
    { id: "device", title: "Device", icon: Smartphone, desc: "PWA, Offline Access, Data-Saver" },
    { id: "popia", title: "POPIA & Privacy", icon: Shield, desc: "Download My Data, Data Portability, Erasure" },
  ];

  const handleDownloadData = async () => {
    setLoading(true);
    try {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) return;

      const [profileData, makerData, walletData] = await Promise.all([
        supabase.from('profiles').select('*').eq('id', user.id).single(),
        supabase.from('makers').select('*').eq('id', user.id).maybeSingle(),
        supabase.from('wallets').select('*').eq('user_id', user.id).maybeSingle(),
      ]);

      const exportData = {
        meta: { exported_at: new Date().toISOString(), system: "ShapaCV v1.0" },
        identity: profileData.data,
        maker_profile: makerData.data,
        financial: { wallet: walletData.data }
      };

      const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `shapa-data-export-${user.id}.json`;
