interface MakerData {
  id: string;
  name: string;
  trade: string;
  location: string;
  bio: string;
  verification_tier: string;
  reliability_score: number;
  recommended_tools?: Array<{
    name: string;
    brand?: string;
    price?: string;
    affiliate_url: string;
    image_url?: string;
  }>;
}

interface Proof {
  id: string;
  video_url: string;
  title: string;
  created_at: string;
}

export default function PublicTalentProfile({ params }: { params: Promise<{ id: string }> }) {
  const resolvedParams = use(params);
  const id = resolvedParams.id;
  const router = useRouter();

  const [loading, setLoading] = useState(true);
  const [maker, setMaker] = useState<MakerData | null>(null);
  const [proofs, setProofs] = useState<Proof[]>([]);
  const [reviews, setReviews] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<"proofs" | "reviews">("proofs");

  useEffect(() => {
    async function fetchProfile() {
      const supabase = createClient();

      // 1. Fetch Maker
      const { data: makerData } = await supabase
        .from('makers')
        .select('*')
        .eq('id', id)
        .single();

      if (makerData) setMaker(makerData as any);

      // 2. Fetch Proofs
      const { data: proofsData } = await supabase
        .from('proofs')
        .select('*')
        .eq('maker_id', id)
        .order('created_at', { ascending: false });

      if (proofsData) setProofs(proofsData as any[]);

      // 3. Fetch Reviews
      const reviewsData = await getReviews(id);
      setReviews(reviewsData);

      setLoading(false);
    }
    fetchProfile();
  }, [id]);

  const handleMessage = async () => {
    try {
      const conv = await createConversation(id);
      router.push(`/messages/${(conv as any).id}`);
    } catch (err) {
      console.error(err);
      alert("Please login to message makers.");
