                     <video src={proof.video_url} className="absolute inset-0 w-full h-full object-cover" muted loop onMouseOver={e => (e.target as any).play()} onMouseOut={e => (e.target as any).pause()} />
                     <div className="absolute inset-0 bg-black/40 group-hover:bg-transparent transition-all pointer-events-none" />
