export default function RecordProof() {
  const router = useRouter();
  const videoRef = useRef<HTMLVideoElement>(null);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const [stream, setStream] = useState<MediaStream | null>(null);
  const [isRecording, setIsRecording] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [recordingTime, setRecordingTime] = useState(0);
  const [maxTime, setMaxTime] = useState(30); // 15, 30, 60
  const [error, setError] = useState<string | null>(null);
  const [activeCue, setActiveCue] = useState(0);
  const [offlineProofs, setOfflineProofs] = useState<OfflineProof[]>([]);
  const [isSyncing, setIsSyncing] = useState(false);

  // Check for offline proofs on mount
  useEffect(() => {
    async function checkOffline() {
      const offline = await getOfflineProofs();
      setOfflineProofs(offline);
    }
    checkOffline();
  }, []);

  const DIRECTOR_CUES = [
    { title: "The Intro", text: "Say: 'I'm [Name] from [Township]. I hustle as a [Trade].'", time: 5 },
    { title: "The Demo", text: "Show us your tools or you working. Pro-tip: Good lighting is key!", time: 20 },
    { title: "The Bag", text: "Say: 'Hire me for the best vibes and solid work. Shapa!'", time: 5 }
  ];

  // Initialize camera stream
  useEffect(() => {
    async function initCamera() {
      try {
        const userStream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user", width: { ideal: 1280 }, height: { ideal: 720 } },
          audio: true,
        });
        setStream(userStream);
        if (videoRef.current) {
          videoRef.current.srcObject = userStream;
        }
      } catch (err) {
        console.error("Error accessing camera:", err);
        setError("Could not access camera/microphone. Please check permissions.");
      }
    }
    initCamera();
    return () => {
      stream?.getTracks().forEach(track => track.stop());
    };
  }, []);

  // Timer logic
  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isRecording) {
      interval = setInterval(() => {
        setRecordingTime((prev) => {
          if (prev >= maxTime) {
            stopRecording();
            return maxTime;
          }

          // Transition cues
          const elapsed = prev + 1;
          if (elapsed <= 5) setActiveCue(0);
          else if (elapsed <= 25) setActiveCue(1);
          else setActiveCue(2);

          return elapsed;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [isRecording, maxTime]);

  const getSupportedMimeType = () => {
    const types = [
      "video/webm;codecs=vp9,opus",
      "video/webm;codecs=vp8,opus",
      "video/webm",
      "video/mp4;codecs=avc1,mp4a.40.2",
      "video/mp4",
      "video/quicktime",
    ];
    for (const type of types) {
      if (MediaRecorder.isTypeSupported(type)) {
        return type;
      }
    }
    return "";
  };

  const startRecording = () => {
    if (!stream) return;
    chunksRef.current = [];

    const mimeType = getSupportedMimeType();
    if (!mimeType) {
      setError("No compatible video recording format found on this device.");
      return;
    }

    try {
      const mediaRecorder = new MediaRecorder(stream, { mimeType });
      mediaRecorderRef.current = mediaRecorder;

      mediaRecorder.ondataavailable = (e) => {
        if (e.data.size > 0) chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = async () => {
        const ext = mimeType.includes("mp4") ? "mp4" : mimeType.includes("quicktime") ? "mov" : "webm";
        const blob = new Blob(chunksRef.current, { type: mimeType });
        await handleUpload(blob, ext);
      };

      mediaRecorder.start();
      setIsRecording(true);
      setRecordingTime(0);
    } catch (err) {
      console.error("Recording start error:", err);
      setError("Failed to start recording. Please try again.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleUpload = async (blob: Blob, ext: string = "webm") => {
    setIsUploading(true);
    setError(null);
    try {
      const formData = new FormData();
      formData.append("file", blob, `recording.${ext}`);

      const response = await fetch("/api/upload", {
        method: "POST",
        body: formData,
      });

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error || "Upload failed");
      }
      const result = await response.json();

      sessionStorage.setItem("proof_video_url", result.url);
      trackEvent(ANALYTICS_EVENTS.VIBECHECK_RECORDED, { url: result.url });
      router.push("/onboarding");
    } catch (err: any) {
      console.error("Upload error:", err);

      // Load Shedding Mode: Save to IndexedDB
      await saveProofOffline(blob, `Proof_${new Date().toISOString()}.${ext}`);
      const offline = await getOfflineProofs();
      setOfflineProofs(offline);

      setError(`Load Shedding Detected 🔋 ${err.message || 'Connection lost'}. We've saved your proof locally!`);
      setIsUploading(false);
    }
  };

  const handleSync = async () => {
    if (offlineProofs.length === 0 || isSyncing) return;
    setIsSyncing(true);
    setIsUploading(true);

    try {
      for (const proof of offlineProofs) {
        const formData = new FormData();
        // Use the stored filename which includes the correct extension (.mp4, .mov, or .webm)
        formData.append("file", proof.blob, proof.filename || "sync.webm");

        const response = await fetch("/api/upload", {
          method: "POST",
          body: formData,
        });

        if (response.ok) {
          await deleteOfflineProof(proof.id);
        }
      }

      const remaining = await getOfflineProofs();
      setOfflineProofs(remaining);
      if (remaining.length === 0) {
        alert("Ziyakhala! 🚀 All proofs synced successfully.");
        router.push("/onboarding");
      }
    } catch (err) {
      console.error("Sync error:", err);
      setError("Still experiencing network issues. We'll try again later!");
    } finally {
      setIsSyncing(false);
      setIsUploading(false);
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
  };

  return (
    <div className="h-screen bg-transparent text-white flex flex-col items-center justify-center p-8 relative overflow-hidden font-sans selection:bg-[#13EC6A]/30">

      {/* Top Navigation */}
      <div className="absolute top-0 w-full p-12 flex justify-between items-center z-30">
        <div className="flex items-center gap-8">
          <Link href="/talent/studio" className="w-16 h-16 rounded-[2rem] glass-card hover:bg-white/10 flex items-center justify-center transition-all border border-white/10 group">
            <X size={32} className="group-hover:rotate-90 transition-transform" />
          </Link>
          <div className="hidden sm:block">
            <h2 className="font-black text-4xl tracking-tighter italic font-display uppercase">Proof Studio.</h2>
            <p className="text-[#13EC6A] text-[10px] font-black uppercase tracking-[0.4em] animate-pulse italic drop-shadow-glow">Live Hustle Session</p>
          </div>
        </div>

        <div className="flex gap-8">
          <div className="glass-card px-8 py-4 rounded-[2rem] flex items-center gap-6 border border-white/10 shadow-premium">
            <div className={`w-3.5 h-3.5 rounded-full ${isRecording ? "bg-red-500 shadow-glow-red animate-pulse" : "bg-gray-700"}`}></div>
            <span className="font-black tracking-[0.3em] text-[10px] italic uppercase">{isRecording ? "RECORDING" : "STANDBY"}</span>
          </div>
          <button className="glass-card hover:bg-[#13EC6A] hover:text-[#052210] px-10 py-4 rounded-[2rem] flex items-center gap-4 border border-white/10 transition-all font-black text-[10px] uppercase tracking-[0.3em] italic">
            Trending <Play size={18} fill="currentColor" className="drop-shadow-glow" />
          </button>
        </div>
      </div>

      {/* Viewfinder - Forced 9:16 for TikTok Vibe */}
      <div className="relative w-full max-w-md aspect-[9/16] bg-black rounded-[4rem] overflow-hidden border-8 border-white/5 shadow-[0_0_120px_rgba(0,0,0,0.9)] mx-auto shimmer-border">
        {error ? (
          <div className="absolute inset-0 flex flex-col items-center justify-center p-16 text-center bg-black/80 backdrop-blur-3xl z-50">
            <RefreshCw className="text-red-500 mb-10 animate-spin-slow" size={80} />
            <p className="text-3xl font-black text-white italic mb-12 max-w-sm tracking-tighter font-display uppercase leading-tight">{error}</p>
            <button onClick={() => window.location.reload()} className="px-16 py-6 bg-[#13EC6A] text-[#052210] rounded-[2rem] border-b-8 border-black/20 hover:scale-105 active:scale-95 transition-all font-black uppercase tracking-[0.3em] italic">Retry Session</button>
          </div>
        ) : (
          <video 
            ref={videoRef}
            autoPlay 
            muted 
            playsInline
            className="absolute inset-0 w-full h-full object-cover scale-x-[-1]"
          />
        )}

        {/* Guideline Overlays */}
        <div className="absolute inset-0 z-10 pointer-events-none">
           {/* Thirds Grid */}
           <div className="grid grid-cols-3 grid-rows-3 w-full h-full opacity-[0.1]">
             <div className="border-b border-r border-white"></div>
             <div className="border-b border-r border-white"></div>
             <div className="border-b border-white"></div>
             <div className="border-b border-r border-white"></div>
             <div className="border-b border-r border-white"></div>
             <div className="border-b border-white"></div>
             <div className="border-r border-white"></div>
             <div className="border-r border-white"></div>
             <div></div>
           </div>

           {/* Professional Framing Target */}
           <div className="absolute inset-0 flex items-center justify-center">
              <div className="w-80 h-80 md:w-[500px] md:h-[500px] border-2 border-[#13EC6A]/10 rounded-full flex items-center justify-center">
                 <div className="w-3 h-3 bg-[#13EC6A]/40 rounded-full shadow-glow" />
              </div>
              <div className="absolute w-16 h-px bg-[#13EC6A]/30" />
              <div className="absolute h-16 w-px bg-[#13EC6A]/30" />
           </div>
        </div>

        {/* Timer Select & Current Time */}
        <div className="absolute top-12 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center">
           {!isRecording && !isUploading && (
             <div className="flex gap-3 glass-card p-2 rounded-[2rem] border border-white/10 mb-8 shadow-premium backdrop-blur-3xl">
               {[15, 30, 60].map(t => (
                 <button 
                  key={t}
                  onClick={() => setMaxTime(t)}
                  className={`px-8 py-3 rounded-[1.5rem] text-[10px] font-black tracking-[0.3em] transition-all italic ${maxTime === t ? "bg-[#13EC6A] text-[#052210] shadow-glow" : "text-gray-500 hover:text-white"}`}
                 >
                   {t}S
                 </button>
               ))}
             </div>
           )}

           <div className="glass-card px-12 py-5 rounded-[2rem] flex items-center gap-8 border border-white/10 shadow-premium backdrop-blur-3xl">
             <div className="flex items-center gap-4">
               <span className="text-4xl font-black font-mono tracking-tighter w-24 text-center text-[#13EC6A] drop-shadow-glow">{formatTime(recordingTime)}</span>
               <span className="text-gray-600 font-black text-xs opacity-50">/ 00:{maxTime}</span>
             </div>
           </div>
        </div>

        {/* Dynamic Action Prompts */}
        <div className="absolute bottom-24 inset-x-0 flex flex-col items-center z-20 px-16 text-center">
            {isUploading ? (
               <div className="glass-card p-16 rounded-[4rem] border border-[#13EC6A]/20 flex flex-col items-center shadow-glow font-body text-center bg-black/40 backdrop-blur-3xl">
                  <Loader2 className="animate-spin text-[#13EC6A] mb-12 drop-shadow-glow" size={80} />
                  <h3 className="text-5xl font-black tracking-tighter mb-4 italic font-display uppercase">Encoding...</h3>
                  <p className="text-gray-500 font-bold text-lg italic">Optimizing for the feed.</p>
               </div>
            ) : (
               <div className="animate-in fade-in slide-in-from-bottom-6 duration-700 flex flex-col items-center max-w-sm mx-auto">
                <h3 className="text-4xl md:text-5xl font-black text-white drop-shadow-[0_20px_100px_rgba(0,0,0,1)] leading-[0.9] font-display italic uppercase">
                  {isRecording ? DIRECTOR_CUES[activeCue]?.text : "Introduce yourself. Show your gear."}
                </h3>
              </div>
            )}
        </div>

        {/* Offline Sync Overlay */}
        {offlineProofs.length > 0 && !isRecording && !isUploading && (
          <div className="absolute top-48 inset-x-0 mx-auto w-max z-40 animate-bounce">
            <button 
              onClick={handleSync}
              className="bg-amber-500 text-black px-8 py-4 rounded-full font-black text-[10px] uppercase tracking-[0.4em] flex items-center gap-4 shadow-premium border-b-4 border-amber-800 italic"
            >
              <CloudLightning size={20} /> {offlineProofs.length} SAVED PROOFS
            </button>
          </div>
        )}
      </div>

      {/* Control Bar */}
      <div className="absolute bottom-12 w-full max-w-5xl px-16 flex justify-between items-center z-30">
        <div className="flex gap-8">
           <button className="w-20 h-20 rounded-[2rem] glass-card hover:bg-white/10 flex items-center justify-center transition-all group p-5 border border-white/10">
             <Zap size={32} className="text-amber-400 group-hover:scale-110 transition-transform drop-shadow-glow" />
           </button>
           <button className="w-20 h-20 rounded-[2rem] glass-card hover:bg-white/10 flex items-center justify-center transition-all group p-5 border border-white/10">
             <Play size={32} className="text-indigo-400 group-hover:scale-110 transition-transform drop-shadow-glow" />
           </button>
        </div>

        <button 
          onClick={isRecording ? stopRecording : startRecording}
          disabled={isUploading}
          className="relative w-40 h-40 flex items-center justify-center group disabled:opacity-50"
        >
          <div className={`absolute inset-0 rounded-full border-[8px] ${isRecording ? "border-red-500/50 animate-ping" : "border-[#13EC6A]/30"}`}></div>
          <div className={`absolute inset-0 rounded-full border-[8px] ${isRecording ? "border-red-500 shadow-glow-red" : "border-[#13EC6A]"} opacity-80 shadow-premium`}></div>
          <div className={`
            w-32 h-32 rounded-[2.5rem] flex items-center justify-center transition-all duration-700
            ${isRecording ? "bg-red-500 scale-90" : "bg-white rounded-full scale-100"}
          `}>
            {isRecording ? <Square fill="white" className="text-white" size={48} /> : <Camera size={56} className="text-black" />}
          </div>
        </button>

        <div className="flex gap-8">
           <input 
             type="file" 
             id="gallery-upload" 
             className="hidden" 
             accept="video/*"
             onChange={async (e) => {
               const file = e.target.files?.[0];
               if (file) await handleUpload(file);
             }}
           />
           <button 
             disabled={isUploading}
             onClick={() => document.getElementById("gallery-upload")?.click()}
             className="hidden sm:flex w-20 h-20 rounded-[2rem] glass-card border border-white/10 items-center justify-center hover:bg-white/10 transition-all text-gray-500 hover:text-white"
           >
             <ImageIcon size={32} />
           </button>
           <button 
             onClick={() => {
                const url = prompt("Paste video URL:");
                if (url) alert("Fetching social proof... (Simulated)");
             }}
             className="w-20 h-20 rounded-[2rem] glass-card border-4 border-white/10 overflow-hidden relative active:scale-95 transition-transform cursor-pointer"
           >
              <div className="absolute inset-x-0 bottom-0 bg-[#13EC6A] text-[#052210] text-[9px] font-black text-center py-1.5 italic uppercase tracking-[0.2em]">Import</div>
              <div className="absolute inset-0 flex items-center justify-center opacity-20">
                 <Zap size={28} />
              </div>
           </button>
        </div>
      </div>
    </div>
  );
}

"use client";
import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { 
  Wallet, 
  ArrowUpRight, 
  ArrowDownLeft, 
  Clock, 
  Download, 
  Filter, 
  CreditCard,
  ShieldCheck,
  TrendingUp,
  ChevronLeft,
  Loader2,
  CheckCircle2
} from "lucide-react";
import { createClient } from "@/utils/supabase/client";
import Link from "next/link";

export default function MakerWallet() {
  const router = useRouter();
  const supabase = createClient();
  const [loading, setLoading] = useState(true);
  const [wallet, setWallet] = useState<any>(null);
  const [transactions, setTransactions] = useState<any[]>([]);

  useEffect(() => {
    async function loadData() {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session) {
          router.push("/onboarding");
          return;
        }

        // Search for wallet
        const { data: walletData, error: walletError } = await supabase
          .from("wallets")
          .select("*")
          .eq("user_id", session.user.id)
          .single();

        if (walletError && walletError.code !== "PGRST116") throw walletError;

        if (walletData) {
          setWallet(walletData);
          const { data: txData } = await supabase
            .from("transactions")
            .select("*")
            .eq("wallet_id", (walletData as any)?.id)
            .order("created_at", { ascending: false });
          setTransactions(txData || []);
        } else {
           // For demo, if no wallet exists, create a dummy one or show zero
           setWallet({ balance: 0.00, pending_balance: 0.00, currency: "ZAR" });
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, [router]);

  if (loading) return <div className="h-screen bg-[#111613] flex items-center justify-center text-[#13EC6A] font-black italic animate-pulse font-display text-2xl">SYNCING WALLET...</div>;

  return (
    <div className="min-h-screen bg-transparent text-white font-sans p-8 lg:p-24 relative overflow-hidden selection:bg-[#13EC6A]/30 mb-20">
      <main className="max-w-5xl mx-auto space-y-20 relative z-10">
        <header className="flex flex-col md:flex-row justify-between items-end border-b border-white/5 pb-16 gap-12">
           <div>
              <p className="text-[#13EC6A] font-black text-[10px] uppercase tracking-[0.5em] mb-8 italic drop-shadow-glow bg-[#13EC6A]/5 px-6 py-2 rounded-full border border-[#13EC6A]/20 inline-block">Financial Hub</p>
              <h1 className="text-8xl font-black italic tracking-tighter mb-6 font-display uppercase leading-none text-glow">My Wallet.</h1>
              <p className="text-gray-500 font-bold max-w-md text-xl italic leading-relaxed">Securely manage your earnings and sync every gig payment with professional precision.</p>
           </div>
           <button className="glass-card hover:bg-white/10 px-10 py-6 rounded-[2rem] border border-white/10 text-[11px] font-black uppercase tracking-[0.3em] flex items-center gap-4 transition-all italic shimmer-border shadow-premium">
              <Download size={22} /> EXPORT IDENTITY STATEMENT
           </button>
        </header>

        {/* Balance Cards */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
           <div className="lg:col-span-2 glass-card bg-gradient-to-br from-[#13EC6A] to-[#0d9b4b] p-16 rounded-[4rem] text-[#052210] relative overflow-hidden shadow-[0_40px_100px_rgba(19,236,106,0.2)] border-b-[12px] border-black/20 group">
              <div className="absolute top-0 right-0 p-16 transform rotate-12 opacity-5 transition-transform group-hover:rotate-45 duration-1000">
                 <Wallet size={240} />
              </div>
              <p className="font-black text-[10px] uppercase tracking-[0.4em] mb-10 opacity-60 italic">Available Balance</p>
              <h2 className="text-9xl font-black tracking-tighter italic mb-16 font-display leading-none">R {wallet?.balance?.toLocaleString() || "0.00"}</h2>
              <button className="w-full bg-[#052210] text-[#13EC6A] font-black py-8 rounded-[2.5rem] text-[12px] uppercase tracking-[0.4em] hover:scale-105 transition-all active:scale-95 shadow-premium italic border-t border-white/10">
                 INSTANT PROTOCOL WITHDRAWAL
              </button>
           </div>

           <div className="glass-card p-16 rounded-[4rem] border border-white/10 flex flex-col justify-between shadow-premium relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 opacity-5">
                <Clock size={120} />
              </div>
              <div>
                 <p className="text-gray-600 font-black text-[10px] uppercase tracking-[0.4em] mb-10 italic">In Secure Escrow</p>
                 <h2 className="text-7xl font-black tracking-tighter italic text-white/90 font-display leading-none">R {wallet?.pending_balance?.toLocaleString() || "0.00"}</h2>
              </div>
              <div className="mt-12 flex items-center gap-6 text-[#13EC6A]">
                 <div className="w-4 h-4 rounded-full bg-[#13EC6A] animate-ping shadow-glow" />
                 <p className="text-[11px] font-black uppercase tracking-[0.3em] italic">SYNCING WITH ESCROW CHAIN...</p>
              </div>
           </div>
        </div>

        {/* Transactions Section */}
        <section className="space-y-12">
           <div className="flex justify-between items-end px-4">
              <h3 className="text-5xl font-black italic tracking-tighter font-display uppercase">Legacy Logs</h3>
              <div className="flex gap-4">
                 <button className="w-14 h-14 glass-card rounded-2xl border border-white/5 text-gray-500 hover:text-white transition-all flex items-center justify-center">
                    <Filter size={24} />
                 </button>
              </div>
           </div>

           <div className="space-y-6">
              {transactions.length > 0 ? (
                transactions.map((tx: any) => (
                   <div key={tx.id} className="glass-card p-10 rounded-[3rem] border border-white/5 flex items-center justify-between group hover:border-[#13EC6A]/30 hover:scale-[1.01] transition-all duration-500 shadow-premium">
                      <div className="flex items-center gap-10">
                         <div className={`w-20 h-20 rounded-[1.5rem] flex items-center justify-center transition-all ${tx.type === 'credit' ? 'bg-[#13EC6A]/10 text-[#13EC6A] shadow-glow' : 'bg-red-500/10 text-red-400'}`}>
                            {tx.type === 'credit' ? <ArrowDownLeft size={32} /> : <ArrowUpRight size={32} />}
                         </div>
                         <div>
                            <p className="font-black text-2xl leading-tight italic uppercase font-display group-hover:text-white transition-colors">{tx.description}</p>
                            <p className="text-[10px] font-black text-gray-600 uppercase tracking-[0.3em] mt-3 italic flex items-center gap-3">
                               <Clock size={12} /> {new Date(tx.created_at).toLocaleDateString('en-ZA', { day: 'numeric', month: 'long', year: 'numeric' })}
                            </p>
                         </div>
                      </div>
                      <div className="text-right">
                         <p className={`text-3xl font-black italic font-display ${tx.type === 'credit' ? 'text-[#13EC6A] drop-shadow-glow' : 'text-white'}`}>
                            {tx.type === 'credit' ? '+' : '-'} R {tx.amount.toLocaleString()}
                         </p>
                         <p className={`text-[10px] font-black uppercase tracking-[0.3em] mt-3 italic ${tx.status === 'completed' ? 'text-[#13EC6A]' : 'text-gray-600'}`}>
                           {tx.status}
                         </p>
                      </div>
                   </div>
                ))
              ) : (
                <div className="text-center py-32 glass-card rounded-[4rem] border-4 border-dashed border-white/5 group">
                   <div className="w-24 h-24 rounded-[2rem] bg-white/[0.03] flex items-center justify-center text-gray-700 mx-auto mb-10 group-hover:scale-110 group-hover:rotate-12 transition-all">
