export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const employerId = searchParams.get("employer_id");

    if (!employerId) {
      return NextResponse.json({ error: "Missing employer_id" }, { status: 400 });
    }

    const { data, error } = await supabase
      .from("jobs")
      .select("*")
      .eq("employer_id", employerId)
      .order("created_at", { ascending: false });

    if (error) {
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ jobs: data });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

export async function POST(req: NextRequest) {
  try {
    const { proof_id, video_url } = await req.json();

    if (!proof_id) {
      return NextResponse.json({ error: "Proof ID is required" }, { status: 400 });
    }

    // 1. Delete from database
    const { error: dbError } = await supabase
      .from("proofs")
      .delete()
      .eq("id", proof_id);

    if (dbError) throw dbError;

    // 2. Delete from storage if video_url is provided
    if (video_url) {
      const fileName = video_url.split("/").pop();
      if (fileName) {
        await supabase.storage.from("proofs").remove([fileName]);
      }
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error("Delete proof error:", error.message || error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { createClient } from "@/utils/supabase/server";
import { NextResponse } from "next/server";
import { revalidatePath } from "next/cache";

export async function POST(request: Request) {
  try {
    const { action, maker_id, job_id } = await request.json();
    const supabase = await createClient();

    const { data: { user } } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ error: "Unauthorized" }, { status: 401 });

    if (action === "promote") {
      const featuredUntil = new Date();
      featuredUntil.setDate(featuredUntil.getDate() + 7);

      const { error } = await (supabase.from("makers") as any)
        .update({ featured_until: featuredUntil.toISOString() })
        .eq("id", maker_id);

      if (error) throw error;

      revalidatePath("/talent/dashboard");
      revalidatePath(`/u/${maker_id}`);

      return NextResponse.json({ success: true, expiry: featuredUntil.toISOString() });
    }

    if (action === "verify") {
      const { error } = await (supabase.from("makers") as any)
        .update({
          verification_paid_at: new Date().toISOString(),
          verification_tier: "trusted",
        })
        .eq("id", maker_id);

      if (error) throw error;

      revalidatePath("/talent/dashboard");
      revalidatePath(`/u/${maker_id}`);

      return NextResponse.json({ success: true });
    }

    return NextResponse.json({ error: "Unknown action" }, { status: 400 });
  } catch (err: any) {
    console.error("Payments API Error:", err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

