import { createClient } from "@supabase/supabase-js";
import { NextRequest, NextResponse } from "next/server";

import { Database } from "@/lib/database.types";

// Use the service-role key for server-side uploads so we bypass RLS
// This key should NEVER be exposed to the browser
const supabaseAdmin = createClient<Database>(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

// Diagnostic: Warn if running in low-privilege mode
if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
  console.warn("⚠️  SUPABASE_SERVICE_ROLE_KEY is missing! API is running with ANON_KEY permissions (RLS applies).");
}

export async function POST(req: NextRequest) {
  try {
    const formData = await req.formData();
    const file = formData.get("file") as File;

    if (!file) {
      return NextResponse.json({ error: "No file provided" }, { status: 400 });
    }

    // Validate file type and size (max 100MB)
    const mimeType = file.type.split(";")[0]; // Strip ";codecs=..." or other parameters
    const allowedTypes = ["video/mp4", "video/webm", "video/quicktime", "video/x-msvideo"];

    if (!allowedTypes.includes(mimeType)) {
      return NextResponse.json({ error: `Only video files (MP4, WebM, MOV, AVI) are allowed. Received: ${file.type}` }, { status: 400 });
    }
    if (file.size > 100 * 1024 * 1024) {
      return NextResponse.json({ error: "File exceeds 100MB limit." }, { status: 400 });
    }

    // Convert File to ArrayBuffer and then to Buffer for the upload
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Generate a unique path: videos/<timestamp>-<random>.<ext>
    const originalName = file.name || "recording.webm";
    const ext = originalName.split(".").pop()?.toLowerCase() || "webm";

    // Safety check on extension
    const validExts = ["mp4", "webm", "mov", "avi"];
    const finalExt = validExts.includes(ext) ? ext : "webm";

    const fileName = `${Date.now()}-${Math.random().toString(36).substring(2)}.${finalExt}`;
    const filePath = `videos/${fileName}`;

    // Upload to the "proofs" Supabase Storage bucket
    const { data, error } = await supabaseAdmin.storage
      .from("proofs")
      .upload(filePath, buffer, {
        contentType: mimeType, // Use cleaned mimeType without codecs
        upsert: false,
      });

    if (error) {
      console.error(`[Upload API] Supabase storage error for ${mimeType}:`, error.message || error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    // Get the public URL for the uploaded file
    const { data: publicUrlData } = supabaseAdmin.storage
      .from("proofs")
      .getPublicUrl(filePath);

    return NextResponse.json({
      url: publicUrlData.publicUrl,
      path: filePath,
    });

  } catch (err: any) {
    console.error("Upload error:", err);
    return NextResponse.json({ error: err.message || "Unknown error" }, { status: 500 });
  }
}

import { createClient } from '@/utils/supabase/server'
import { NextResponse } from 'next/server'

export async function GET(request: Request) {
  const { searchParams, origin } = new URL(request.url)
  const code = searchParams.get('code')
  // If "next" is in param, use it as the redirect URL
  const next = searchParams.get('next') ?? '/'

  if (code) {
    const supabase = await createClient()
    const { error } = await supabase.auth.exchangeCodeForSession(code)
    if (!error) {
      const { data: { user } } = await supabase.auth.getUser()

      const { data: profile } = await supabase
        .from('profiles')
        .select('role')
        .eq('id', (user?.id as string) || '')
        .single()

      // If no role, intercept them to choose their path before proceeding
      if (profile && !(profile as any).role) {
        return NextResponse.redirect(`${origin}/role-select`)
      }

      // Otherwise proceed to intended next or dashboard
      return NextResponse.redirect(`${origin}${next === '/' ? '/dashboard' : next}`)
    }
  }

  // Return the user to an error page with instructions
  return NextResponse.redirect(`${origin}/auth/auth-code-error`)
}

