export default function ShapaOnboarding() {
  const router = useRouter();
  const [step, setStep] = useState<Step>(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [isEmailSent, setIsEmailSent] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    dob: "",
    password: "",
    province: "",
    city: "",
    township: "",
    skills: [] as string[],
    userType: "" as "talent" | "employer", // talent or employer
    role: "hustler", // hustler, freshie, graduate, reskiller
  });

  // 1. Session Check for auto-advance and data prep
  useEffect(() => {
    const supabase = createClient();
    const checkSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        // Prep initial data from Google session if empty
        setFormData(prev => ({
          ...prev,
          name: prev.name || session.user.user_metadata?.full_name || "",
          email: prev.email || session.user.email || "",
        }));

        if (step === 0) setStep(1); // Advance to Identity if already logged in
      }
    };
    checkSession();
  }, [step]);

  const handleInitialSignUp = async () => {
    if (!formData.name || !formData.email || !formData.password) {
      setError("All account fields are required.");
      return;
    }

    setLoading(true);
    setError(null);
    const supabase = createClient();

    try {
      const { data, error: signUpError } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.password,
        options: {
          data: {
            full_name: formData.name,
          }
        }
      });

      if (signUpError) throw signUpError;

      // Track Signup
      trackEvent(formData.userType === 'employer' ? ANALYTICS_EVENTS.EMPLOYER_SIGNUP : ANALYTICS_EVENTS.TALENT_SIGNUP, {
        email: formData.email
      });

      // If we got a user, we proceed to Step 1. 
      // Confirmation will happen in the background or at final save.
      setStep(1);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const saveProfile = async () => {
    setLoading(true);
    setError(null);
    try {
      const supabase = createClient();
      let { data: { user } } = await supabase.auth.getUser();

      // If no confirmed user yet, we might still have data in auth.users if they just signed up
      if (!user) {
        // Fallback: check session again or just attempt anonymous upsert (won't work for RLS)
        const { data: sessionData } = await supabase.auth.getSession();
        user = sessionData.session?.user || null;
      }

      // If still no user, we check if they are in the "Email Sent" pool
      if (!user) {
        setIsEmailSent(true);
        return true;
      }

      const userId = user.id;
      // Map 'talent' UI label to 'hustler' database role
      const isTalent = formData.userType === 'talent';
      const userRole: ProfileRole = isTalent ? 'hustler' : 'employer';
      const locationString = `${formData.township}, ${formData.city}, ${formData.province}`;

      // 1. Update profiles role using Hub
      await profilesHub.upsert({
        id: userId,
        role: userRole,
        updated_at: new Date().toISOString()
      });

      // 2. Update makers table ONLY if user is talent
      if (isTalent) {
        await makersHub.upsert({
          id: userId,
          name: formData.name || user.user_metadata?.full_name || "Anonymous",
          phone: formData.phone || null,
          location: locationString,
          province: formData.province || null,
          city: formData.city || null,
          township: formData.township || null,
          trade: formData.skills[0] || "General Hustler",
          skills: formData.skills.length > 0 ? formData.skills : null,
          role: formData.role || 'hustler',
          onboarded: true,
          updated_at: new Date().toISOString()
        });
      }

      // Track Publishing
      trackEvent(ANALYTICS_EVENTS.VIBECHECK_PUBLISHED, {
        user_type: formData.userType,
        has_video: !!sessionStorage.getItem("proof_video_url")
      });

      return true;
    } catch (err: any) {
      setError(err.message);
      return false;
    } finally {
      setLoading(false);
    }
  };

  const [hasVideo, setHasVideo] = useState(false);
  const [showSkipModal, setShowSkipModal] = useState(false);

  useEffect(() => {
    if (typeof window !== "undefined") {
      setHasVideo(!!sessionStorage.getItem("proof_video_url"));
    }
  }, [step]);

  return (
    <div className="min-h-screen bg-[#111613] text-white flex flex-col items-center justify-center p-6 bg-[url('https://www.transparenttextures.com/patterns/dark-matter.png')]">
      <div className="w-full max-w-2xl">
        <header className="flex justify-between items-center mb-16">
           <div className="flex items-center gap-3 group px-4 py-2 glass rounded-2xl border border-white/5">
             <div className="w-10 h-10 rounded-xl bg-[#13EC6A] flex items-center justify-center text-[#052210] shadow-glow group-hover:rotate-12 transition-transform">
               <Gem size={22} />
             </div>
             <span className="font-black text-2xl tracking-tighter italic font-display">ShapaCV.</span>
           </div>
           <div className="text-[10px] font-black uppercase tracking-[0.3em] text-gray-500 glass px-5 py-2 rounded-full border border-white/5">
             Step {step} <span className="text-[#13EC6A]/40 mx-1">/</span> 4
           </div>
        </header>

        <div className="mb-16 flex gap-3 px-1">
           {[1, 2, 3, 4].map(s => (
              <div key={s} className={`h-1.5 flex-1 rounded-full transition-all duration-700 ${step >= s ? "bg-[#13EC6A] shadow-glow" : "bg-white/5 border border-white/5"}`} />
           ))}
        </div>

        {error && (
          <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-2xl mb-8 text-sm font-bold animate-shake">
            ⚠️ {error}
          </div>
        )}

        {isEmailSent ? (
          <div className="text-center space-y-8 animate-in zoom-in-95 duration-700 font-body">
            <div className="w-24 h-24 bg-[#13EC6A]/10 rounded-[2rem] flex items-center justify-center text-[#13EC6A] mx-auto mb-8 border border-[#13EC6A]/20 shadow-glow">
              <Mail size={48} className="animate-bounce" />
            </div>
            <h1 className="text-5xl font-black mb-4 font-display italic text-glow uppercase tracking-tighter leading-none">
              Ziyakhala! <br/>Check Your Inbox.
            </h1>
