"use client";

import { useEffect, useState, use } from "react";
import { createClient } from "@/utils/supabase/client";
import { 
  Play, MapPin, MessageSquare, Share2, Zap, Star, ShieldCheck, 
  Globe, Video, MessageCircle, Lock, ShieldAlert, Wrench, Gem, ArrowRight
} from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { VerificationBadge } from "@/components/VerificationBadge";
import { createConversation } from "@/lib/actions/messages";
import { getReviews, submitReview } from "@/lib/actions/reviews";

interface Maker {
  id: string;
  name: string;
  trade: string;
  location: string;
  bio: string;
  verification_tier: string;
  reliability_score: number;
  recommended_tools?: Array<{
    name: string;
    brand?: string;
    price?: string;
    affiliate_url: string;
    image_url?: string;
  }>;
}

type Props = {
  params: Promise<{
    username: string;
  }>;
};

export default function CanonicalProfilePage({ params }: Props) {
  const resolvedParams = use(params);
  const identifier = resolvedParams.username; // Can be username or UUID
  const router = useRouter();

  const [maker, setMaker] = useState<Maker | null>(null);
  const [proofs, setProofs] = useState<any[]>([]);
  const [reviews, setReviews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<"proofs" | "reviews" | "toolbox">("proofs");
  const [sessionUser, setSessionUser] = useState<any>(null);

  useEffect(() => {
    async function fetchProfile() {
      const supabase = createClient();
      const { data: { user } } = await supabase.auth.getUser();
      setSessionUser(user);

      let profileId = identifier;

      // 1. Try to find by username first
      const { data: profileByUsername } = await supabase
        .from('profiles')
        .select('*')
        .eq('username', identifier)
        .single();

      if (profileByUsername) {
        profileId = (profileByUsername as any).id;
      }

      // 2. Fetch Maker Data
      const { data: makerData } = await supabase
        .from('makers')
        .select('*')
        .eq('id', profileId)
        .single();

      // 3. Fetch Base Profile if we didn't get it by username (meaning identifier was an ID)
      let finalProfile = profileByUsername;
      if (!profileByUsername && makerData) {
        const { data: p } = await supabase.from('profiles').select('*').eq('id', profileId).single();
        finalProfile = p;
      }

      if (finalProfile && makerData) {
        setMaker({ ...(finalProfile as any), ...(makerData as any) });

        // Load proofs
        const { data: proofsData } = await supabase
          .from('proofs')
          .select('*')
          .eq('maker_id', profileId)
          .order('created_at', { ascending: false });

        if (proofsData) setProofs(proofsData);

        // Load reviews
        const reviewsData = await getReviews(profileId);
        setReviews(reviewsData);
      }

      setLoading(false);
    }
    fetchProfile();
  }, [identifier]);

  const handleHire = async () => {
    if (!sessionUser) {
      alert("Sign in to hire verified talent. 🇿🇦");
      router.push(`/login?next=/u/${identifier}`);
      return;
    }

    // Route directly to the new Escrow Contract generator
    router.push(`/employer/escrow/new?maker_id=${maker!.id}`);
  };

