"use client";

import { useEffect, useState } from "react";
import { Zap, CloudLightning } from "lucide-react";
import { createClient } from "@/utils/supabase/client";
import { settingsHub } from "@/lib/supabase-helpers";

export function LoadSheddingBanner() {
  const [active, setActive] = useState(false);
  const supabase = createClient();

  useEffect(() => {
    // 1. Initial Fetch
    async function init() {
      const val = await settingsHub.get('load_shedding_mode');
      if (val !== null) {
        setActive(val === "true" || val === true);
      }
    }
    init();

    // 2. Realtime Subscription
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: 'UPDATE',
          schema: 'public',
          table: 'site_settings',
          filter: 'key=eq.load_shedding_mode'
        },
        (payload) => {
          const newVal = payload.new.value;
          setActive(newVal === "true" || newVal === true);
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, []);

  if (!active) return null;

  return (
    <div className="w-full bg-amber-600 text-black py-4 px-8 flex items-center justify-center gap-6 relative z-[100] animate-in slide-in-from-top duration-700 shadow-glow-amber">
      <CloudLightning className="animate-bounce" size={24} />
      <div className="flex flex-col md:flex-row items-center gap-2 md:gap-8">
        <span className="font-black italic uppercase tracking-[0.2em] text-sm">Load Shedding Active 🔋</span>
        <p className="text-[10px] font-bold uppercase tracking-widest opacity-80">Syncing may be slower. Video proofs saved offline automatically.</p>
      </div>
      <Zap size={24} className="opacity-40" />
    </div>
  );
}

