"use client";

import { useEffect, useState } from "react";
import { usePathname, useSearchParams } from "next/navigation";

export default function NavigationProgress() {
  const pathname = usePathname();
  const searchParams = useSearchParams();
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);

  useEffect(() => {
    // Start progress on path change
    setLoading(true);
    setProgress(30);

    const timer = setTimeout(() => {
      setProgress(70);
    }, 200);

    const finishTimer = setTimeout(() => {
      setProgress(100);
      setTimeout(() => {
        setLoading(false);
        setProgress(0);
      }, 200);
    }, 500);

    return () => {
      clearTimeout(timer);
      clearTimeout(finishTimer);
    };
  }, [pathname, searchParams]);

  if (!loading) return null;

  return (
    <div className="fixed top-0 left-0 right-0 z-[10000] pointer-events-none h-[3px]">
      <div 
        className="h-full bg-[#13EC6A] transition-all duration-500 ease-out shadow-[0_0_15px_rgba(19,236,106,0.8)]"
        style={{ width: `${progress}%` }}
      />
      <div className="absolute top-0 right-0 w-24 h-full bg-gradient-to-r from-transparent to-[#13EC6A] animate-pulse blur-sm" 
           style={{ left: `${progress - 5}%` }} />
    </div>
  );
}

"use client";

import { useState, useEffect } from "react";
import { X, Download, Gem } from "lucide-react";

export default function PWAInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);
  const [showPrompt, setShowPrompt] = useState(false);

  useEffect(() => {
    const handler = (e: any) => {
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault();
      // Stash the event so it can be triggered later.
      setDeferredPrompt(e);
      // Update UI notify the user they can install the PWA
      setShowPrompt(true);
    };

    window.addEventListener("beforeinstallprompt", handler);

    return () => {
      window.removeEventListener("beforeinstallprompt", handler);
    };
  }, []);

  const handleInstall = async () => {
    if (!deferredPrompt) return;

    // Show the install prompt
    deferredPrompt.prompt();

    // Wait for the user to respond to the prompt
    const { outcome } = await deferredPrompt.userChoice;

    if (outcome === "accepted") {
      console.log("User accepted the PWA install prompt");
    } else {
      console.log("User dismissed the PWA install prompt");
    }

    // We've used the prompt, and can't use it again, throw it away
    setDeferredPrompt(null);
    setShowPrompt(false);
  };

  if (!showPrompt) return null;

  return (
    <div className="fixed bottom-6 left-6 right-6 z-[100] animate-in slide-in-from-bottom-8 duration-500">
      <div className="bg-[#1CD79D] text-black p-6 rounded-[2.5rem] shadow-[0_20px_50px_rgba(28,215,157,0.4)] flex items-center justify-between border-4 border-white/20 backdrop-blur-xl">
        <div className="flex items-center gap-5">
          <div className="w-14 h-14 bg-black rounded-2xl flex items-center justify-center text-[#1CD79D] shadow-inner">
            <Gem size={28} />
          </div>
          <div>
            <h4 className="font-black text-lg tracking-tighter italic leading-none mb-1">Install Shapa.</h4>
            <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Faster access & Offline mode</p>
          </div>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={handleInstall}
            className="bg-black text-[#1CD79D] px-6 py-3 rounded-xl font-black text-xs uppercase tracking-widest hover:scale-105 active:scale-95 transition-all flex items-center gap-2"
          >
            <Download size={16} /> Install
          </button>
          <button 
            onClick={() => setShowPrompt(false)}
            className="w-10 h-10 rounded-full border border-black/10 flex items-center justify-center text-black/40 hover:text-black hover:bg-black/5 transition-all"
          >
            <X size={20} />
          </button>
        </div>
      </div>
    </div>
  );
}

