import { createClient } from "@/utils/supabase/client";

/**
 * Client-side message and conversation helpers for ShapaCV.
 * Uses the client Supabase SDK — safe to import from Client Components.
 */

export async function sendMessage(conversationId: string, text: string) {
  const supabase = createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("Unauthorized");

  const { data, error } = await (supabase.from("messages") as any)
    .insert({
      conversation_id: conversationId,
      sender_id: user.id,
      text: text,
      is_read: false,
    })
    .select()
    .single();

  if (error) throw error;

  // Update last_message in conversation
  await (supabase.from("conversations") as any)
    .update({
      last_message: text,
      updated_at: new Date().toISOString(),
    })
    .eq("id", conversationId);

  return data;
}

export async function createConversation(otherUserId: string) {
  const supabase = createClient();

  const { data: { user } } = await supabase.auth.getUser();
  if (!user) throw new Error("Unauthorized");

  // Check if conversation already exists
  const { data: existing } = await supabase
    .from("conversations")
    .select("id")
    .or(`and(user_1_id.eq.${user.id},user_2_id.eq.${otherUserId}),and(user_1_id.eq.${otherUserId},user_2_id.eq.${user.id})`)
    .single();

  if (existing) return existing;

  // Create new
  const { data, error } = await (supabase.from("conversations") as any)
    .insert({
      user_1_id: user.id,
      user_2_id: otherUserId,
    })
    .select()
    .single();

  if (error) throw error;
  return data;
}

"use server";

import { createClient } from "@/utils/supabase/server";
import { revalidatePath } from "next/cache";

/**
 * Promotes a maker to "Featured" status for 7 days.
 * In a real app, this would be preceded by a successful payment gateway callback.
 */
export async function promoteMaker(makerId: string) {
  const supabase = await createClient();

  // Calculate expiry (7 days from now)
  const featuredUntil = new Date();
  featuredUntil.setDate(featuredUntil.getDate() + 7);

  const { error } = await (supabase
    .from("makers") as any)
    .update({ 
      featured_until: featuredUntil.toISOString() 
    })
    .eq("id", makerId);

  if (error) {
    console.error("Promotion Error:", error.message || error);
    throw new Error(`Failed to promote maker: ${error.message}`);
  }

  revalidatePath("/discovery");
  revalidatePath("/talent/dashboard");
  revalidatePath(`/talent/${makerId}`);

  return { success: true, expiry: featuredUntil.toISOString() };
}

/**
 * Checks if a maker is currently featured.
 */
export async function isFeatured(makerId: string) {
  const supabase = await createClient();

  const { data, error } = await (supabase
    .from("makers") as any)
    .select("featured_until")
    .eq("id", makerId)
    .single();

  if (error || !data?.featured_until) return false;

  const expiry = new Date(data.featured_until as string);
  return expiry > new Date();
}

