      .from('public_makers')
      .select('*, proofs(*), reviews(*)')
      .eq('id', id)
      .maybeSingle(); 
    if (error) {
      console.warn('[makersHub.fetchRich] Supabase error:', error.message, error.code);
      return null;
    }
    return data as any;
  },
  insert: async (values: Database['public']['Tables']['makers']['Insert'], client?: any) => {
    const { error } = await (useClient(client).from('makers') as any).insert(values);
    if (error) throw error;
  },
  update: async (id: string, values: Database['public']['Tables']['makers']['Update'], client?: any) => {
    const { error } = await (useClient(client).from('makers') as any).update(values).eq('id', id);
    if (error) throw error;
  },
  upsert: async (values: Database['public']['Tables']['makers']['Insert'], client?: any) => {
    const { error } = await (useClient(client).from('makers') as any).upsert(values);
    if (error) throw error;
  },
  addSkill: async (makerId: string, skill: string, client?: any) => {
    const { data: maker } = await useClient(client).from('makers').select('skills').eq('id', makerId).single();
    const skills = (maker as any)?.skills || [];
    if (!skills.includes(skill)) {
      const { error } = await (useClient(client).from('makers') as any).update({ skills: [...skills, skill] }).eq('id', makerId);
      if (error) throw error;
    }
  },
  removeSkill: async (makerId: string, skill: string, client?: any) => {
    const { data: maker } = await useClient(client).from('makers').select('skills').eq('id', makerId).single();
    const skills = (maker as any)?.skills || [];
    const { error } = await (useClient(client).from('makers') as any).update({ skills: skills.filter((s: string) => s !== skill) }).eq('id', makerId);
    if (error) throw error;
  }
};

