// --- Storage Integrations ---
const uploadFile = async (bucket: 'proofs' | 'voice-notes', file: File | Blob | Buffer, userId: string, subfolder: string = '', ext: string = 'webm', client?: any) => {
  const fileName = `${userId}/${subfolder ? subfolder + '/' : ''}${Date.now()}.${ext}`;
  const contentType = ext === 'mp4' ? (bucket === 'proofs' ? 'video/mp4' : 'audio/mp4') : (bucket === 'proofs' ? 'video/webm' : 'audio/webm');

  const { data, error } = await useClient(client).storage.from(bucket).upload(fileName, file, {
    contentType,
    cacheControl: '3600',
    upsert: false
  });
  if (error) throw error;
  return useClient(client).storage.from(bucket).getPublicUrl(data.path).data.publicUrl;
};

export const storageHub = {
  uploadProof: async (file: File | Blob, makerId: string, ext: string = 'webm', client?: any) => {
    return uploadFile('proofs', file, makerId, '', ext, client);
  },
  uploadVoiceNote: async (blob: Blob, userId: string, format: 'webm' | 'mp4' = 'webm', client?: any) => {
    return uploadFile('voice-notes', blob, userId, '', format, client);
  },
  deleteFile: async (bucket: 'proofs' | 'voice-notes', path: string, client?: any) => {
    const { error } = await useClient(client).storage.from(bucket).remove([path]);
    if (error) throw error;
  }
};

import { createClient } from "@/utils/supabase/client";
import { Database } from "@/lib/database.types";

/**
 * Escrow Logic for ShapaCV
 * 
 * 1. Employer initiates payment.
 * 2. Funds are deducted from Employer balance.
 * 3. Funds are added to Maker's 'pending_balance'.
 * 4. Transaction is recorded as 'escrow'.
 * 5. Upon completion, funds move from 'pending_balance' to 'balance'.
 */

export async function initiateEscrow(walletId: string, jobId: string, amount: number) {
  const supabase = createClient();

  const { data, error } = await supabase
    .from('transactions')
    // @ts-ignore
    .insert({
      wallet_id: walletId,
      type: 'escrow',
      amount,
      description: `Escrow hold for Job: ${jobId}`,
      status: 'pending'
    })
    .select()
    .single();

  if (error) throw error;
  return data;
}

export async function releaseEscrow(transactionId: string) {
  const supabase = createClient();

  // 1. Update transaction status
  const { error } = await supabase
    .from('transactions')
    // @ts-ignore
    .update({ status: 'completed' })
    .eq('id', transactionId);

  if (error) throw error;

  return { success: true };
}

import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'
import { Database } from '@/lib/database.types'

export async function middleware(request: NextRequest) {
  let supabaseResponse = NextResponse.next({
    request,
  })

  const supabase = createServerClient<Database>(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value, options }) => request.cookies.set(name, value))
          supabaseResponse = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) =>
            supabaseResponse.cookies.set(name, value, options)
          )
        },
      },
    }
  )

  // Refresh session if expired
  const { data: { user } } = await supabase.auth.getUser()

  // Define public routes that don't need authentication
  const publicRoutes = [
    '/',
    '/login',
    '/signup',
    '/role-select',
    '/onboarding',
    '/privacy',
    '/terms',
    '/vibe/',
    '/links/',
    '/talent/',
    '/employer/',
    '/jobs',
    '/auth/',
    '/api/',
  ]
  const isPublicRoute = publicRoutes.some(route => request.nextUrl.pathname === route || request.nextUrl.pathname.startsWith(route))

  if (!user && !isPublicRoute) {
    // Redirect unauthenticated users to login
    const url = request.nextUrl.clone()
    url.pathname = '/login'
    return NextResponse.redirect(url)
  }

  // Middleware should be lightweight. Role-based protection moved to layout/page level.
  return supabaseResponse
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for:
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico (favicon)
     * - auth/callback (OAuth callback)
     * Feel free to modify this pattern as needed.
     */
    '/((?!_next/static|_next/image|favicon.ico|auth/callback).*)',
  ],
}

import { createClient } from "@supabase/supabase-js";
import fs from "fs";
import path from "path";

// ShapaCV Automated Daily Backup Script 🗄️🛡️
// Ensures a ruthless audit trail for SARS and POPIA compliance.

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error("❌ Missing Supabase environment variables. Check .env.local");
  process.exit(1);
}

if (!process.env.SUPABASE_SERVICE_ROLE_KEY) {
  console.warn("⚠️  SUPABASE_SERVICE_ROLE_KEY missing. Using ANON_KEY (Backup may be incomplete due to RLS).");
}

console.log(`🔗 Connecting to: ${supabaseUrl}`);
const supabase = createClient(supabaseUrl, supabaseKey);

const TABLES = ["profiles", "makers", "public_makers", "wallets", "transactions", "contracts", "consent_logs"];

async function runBackup() {
  const timestamp = new Date().toISOString().replace(/[:.]/g, "-");
  const backupDir = path.join(process.cwd(), "backups", timestamp);

  if (!fs.existsSync(backupDir)) {
    fs.mkdirSync(backupDir, { recursive: true });
  }

  console.log(`🚀 Starting Zero-Sugar Backup: ${timestamp}`);

  for (const table of TABLES) {
    const { data, error, count } = await supabase.from(table).select("*", { count: 'exact' });

    if (error) {
      console.error(`❌ Failed to export ${table}:`, error.message);
      continue;
    }

    const rowCount = data?.length || 0;
    console.log(`..Exported ${table}: ${rowCount} rows`);

    fs.writeFileSync(
      path.join(backupDir, `${table}.json`),
      JSON.stringify(data, null, 2)
    );
  }

  console.log(`✅ Backup Complete: ${backupDir}`);
  process.exit(0);
}

runBackup().catch(console.error);

